  // ── Operating Units migration ────────────────────────────────────────────────
  // Rename legacy locationType='outlet' rows to 'operating_unit' and
  // auto-create a "Main Operation" unit for any company that has none.
  (async function migrateOperatingUnits() {
    try {
      await db.execute(sql`
        CREATE TABLE IF NOT EXISTS _migrations (
          name TEXT PRIMARY KEY,
          applied_at TIMESTAMPTZ DEFAULT NOW()
        )
      `);
      const existingRows = await db.execute(
        sql`SELECT name FROM _migrations WHERE name = 'operating_units_rename'`
      );
      const existing = Array.isArray(existingRows)
        ? existingRows[0]
        : (existingRows as any).rows?.[0];
      if (!existing) {
        // 1. Rename 'outlet' → 'operating_unit'
        await db.execute(sql`
          UPDATE inventory_locations
          SET location_type = 'operating_unit'
          WHERE location_type = 'outlet'
        `);
        // 2. Auto-create "Main Operation" for companies that have no operating_unit rows
        await db.execute(sql`
          INSERT INTO inventory_locations
            (id, company_id, name, normalized_name, location_type, source_system, active, created_at, updated_at)
          SELECT
            gen_random_uuid(),
            cs.company_id,
            'Main Operation',
            'main operation',
            'operating_unit',
            'manual',
            1,
            NOW(),
            NOW()
          FROM (SELECT DISTINCT company_id FROM company_stores WHERE status = 'active') cs
          WHERE NOT EXISTS (
            SELECT 1 FROM inventory_locations il
            WHERE il.company_id = cs.company_id
              AND il.location_type = 'operating_unit'
              AND il.active = 1
          )
        `);
        await db.execute(
          sql`INSERT INTO _migrations (name) VALUES ('operating_units_rename')`
        );
        console.log("[Migration] Applied operating_units_rename");
      } else {
        console.log("[Migration] Already applied (operating_units_rename)");
      }
    } catch (err) {
      console.error("[Migration] operating_units_rename error:", err);
    }
  })();

  // GET /api/background-images — public
  // Returns active images. If ?companyId= is provided and company has a brand image, returns just that.
  // For free-tier companies without a brand image, returns the designated free-tier background (if any).
  app.get("/api/background-images", async (req, res) => {
    try {
      const { companyId } = req.query as { companyId?: string };

      if (companyId) {
        const [company] = await db.select({
          brandImagePath: companiesTable.brandImagePath,
          subscriptionPlan: companiesTable.subscriptionPlan,
        })
          .from(companiesTable)
          // @ts-ignore
          .where(eq(companiesTable.id, companyId));

        if (company?.brandImagePath) {
          return res.json({
            images: [{ url: company.brandImagePath, label: "Brand background" }],
            isBranded: true,
          });
        }

        const effectivePlan = company?.subscriptionPlan;
        if (!effectivePlan) {
          const [freeImg] = await db.select()
            .from(backgroundImages)
            // @ts-ignore
            .where(and(eq(backgroundImages.isFreeBackground, 1), eq(backgroundImages.isActive, 1)))
            .limit(1);
          if (freeImg) {
            return res.json({
              images: [{ id: freeImg.id, url: freeImg.objectPath ?? freeImg.externalUrl, label: freeImg.label }],
              isBranded: false,
            });
          }
        }
      }

      const images = await db.select()
        .from(backgroundImages)
        // @ts-ignore
        .where(eq(backgroundImages.isActive, 1))
        // @ts-ignore
        .orderBy(asc(backgroundImages.sortOrder), asc(backgroundImages.createdAt));

      return res.json({
        // @ts-ignore
        images: images.map((img) => ({
          id: img.id,
          url: img.objectPath ?? img.externalUrl,
          label: img.label,
        })),
        isBranded: false,
      });
    } catch (err) {
      console.error("GET /api/background-images error:", err);
      return res.status(500).json({ error: "Failed to fetch background images" });
    }
  });

  // GET /api/mobile/background-images — no auth required
  // Returns active images flagged for mobile use, ordered by sortOrder.
  // Shape: { images: [{ id, url, label }] }
  app.get("/api/mobile/background-images", async (req, res) => {
    try {
      const images = await db.select()
        .from(backgroundImages)
        // @ts-ignore
        .where(and(eq(backgroundImages.isActive, 1), eq(backgroundImages.isMobileAvailable, 1)))
        // @ts-ignore
        .orderBy(asc(backgroundImages.sortOrder), asc(backgroundImages.createdAt));

      return res.json({
        // @ts-ignore
        images: images.map((img) => ({
          id: img.id,
          url: img.objectPath ?? img.externalUrl,
          label: img.label,
        })),
      });
    } catch (err) {
      console.error("GET /api/mobile/background-images error:", err);
      return res.status(500).json({ error: "Failed to fetch mobile background images" });
    }
  });

