  // Prepare invitation acceptance (stores token in cookie for SSO callback)
  // @ts-ignore
  app.post("/api/invitations/prepare-acceptance/:token", async (req, res) => {
    try {
      const { token } = req.params;
      
      // Validate the invitation token
      const invitation = await storage.getInvitationByToken(token);
      
      if (!invitation) {
        return res.status(404).json({ error: "Invitation not found or expired" });
      }
      
      // Store the invitation token in a signed cookie (survives OAuth redirect)
      // Cookie expires in 15 minutes
      res.cookie('pendingInvitation', token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        signed: true,
        maxAge: 15 * 60 * 1000, // 15 minutes
        sameSite: 'lax', // Allow cookie to be sent on OAuth redirects
      });
      
      console.log('[Invitation] Stored invitation token in signed cookie');
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Accept invitation with local auth (username/password flow)
  // @ts-ignore
  app.post("/api/invitations/accept-local", async (req, res) => {
    try {
      const { token, firstName, lastName, password } = req.body;

      if (!token || !firstName || !lastName || !password) {
        return res.status(400).json({ error: "token, firstName, lastName, and password are required" });
      }

      const invitation = await storage.getInvitationByToken(token);
      if (!invitation) {
        return res.status(404).json({ error: "Invitation not found, expired, or already used" });
      }

      // Prevent duplicate accounts
      const existingUser = await storage.getUserByEmail(invitation.email);
      if (existingUser) {
        return res.status(409).json({ error: "An account with this email already exists. Please sign in instead." });
      }

      const passwordHash = await hashPassword(password);

      const newUser = await storage.createUser({
        email: invitation.email,
        passwordHash,
        ssoProvider: "password",
        firstName,
        lastName,
        role: invitation.role as any,
        companyId: invitation.companyId,
        // @ts-ignore
        isActive: 1,
      });

      // Assign to specific stores from the invitation
      for (const storeId of invitation.storeIds) {
        await storage.assignUserToStore(newUser.id, storeId).catch(() => {});
      }

      // company_admin gets access to all company stores
      if (invitation.role === "company_admin") {
        // @ts-ignore
        const allStores = await db.select().from(companyStores).where(eq(companyStores.companyId, invitation.companyId));
        for (const s of allStores) {
          await storage.assignUserToStore(newUser.id, s.id).catch(() => {});
        }
      }

      // Mark invitation as accepted
      // @ts-ignore
      await db.update(invitations).set({ acceptedAt: new Date() }).where(eq(invitations.token, token));

      // Create session (auto-login)
      const sessionToken = await createSession(newUser.id, req.headers["user-agent"], req.ip);
      res.cookie("session", sessionToken, sessionCookieOptions());

      console.log(`[Invitation] Accepted by ${newUser.email} (${newUser.role}) for company ${newUser.companyId}`);

      res.json({
        user: {
          id: newUser.id,
          email: newUser.email,
          role: newUser.role,
          companyId: newUser.companyId,
        },
      });
    } catch (error: any) {
      console.error("[Invitation] accept-local error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Create invitation (admin only)
  // @ts-ignore
  app.post("/api/invitations", requireAuth, async (req, res) => {
    try {
      const currentUser = (req as any).user;
      const { email, role, storeIds } = req.body;

      // Only global admins and company admins can send invitations
      if (currentUser.role !== "global_admin" && currentUser.role !== "company_admin") {
        return res.status(403).json({ error: "Insufficient permissions" });
      }

      // Validate required fields
      if (!email || !role) {
        return res.status(400).json({ error: "Email and role are required" });
      }

      // Company admins can only invite to their company
      const companyId = currentUser.role === "company_admin" 
        ? currentUser.companyId 
        : req.body.companyId;

      if (!companyId) {
        return res.status(400).json({ error: "Company ID is required" });
      }

      // Company admins cannot invite global admins
      if (currentUser.role === "company_admin" && role === "global_admin") {
        return res.status(403).json({ error: "Cannot invite global admins" });
      }

      // Validate store assignments for store_user and store_manager roles
      const storeIdsArray = Array.isArray(storeIds) ? storeIds : [];
      if ((role === "store_user" || role === "store_manager") && storeIdsArray.length === 0) {
        return res.status(400).json({ error: "Store users and store managers must be assigned to at least one store" });
      }

      // Normalize email to lowercase
      const normalizedEmail = email.toLowerCase().trim();

      // Check if user already exists in THIS company
      const existingUser = await storage.getUserByEmail(normalizedEmail);
      if (existingUser && existingUser.companyId === companyId) {
        return res.status(400).json({ error: "User is already a member of this company" });
      }

      // Check if there's already a pending invitation for this email and company
      const existingInvitation = await storage.getInvitationByEmail(normalizedEmail, companyId);
      if (existingInvitation) {
        return res.status(400).json({ error: "Pending invitation already exists for this email" });
      }

      // Generate secure token
      const token = crypto.randomBytes(32).toString("hex");

      // Set expiration (7 days from now)
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 7);

      // Create invitation
      const invitation = await storage.createInvitation({
        email: normalizedEmail,
        companyId,
        role,
        storeIds: storeIdsArray,
        token,
        invitedBy: currentUser.id,
        expiresAt,
      });

      // Send invitation email (fire-and-forget)
      const inviteBaseUrl = process.env.APP_BASE_URL || `${req.protocol}://${req.get("host")}`;
      const inviteUrl = `${inviteBaseUrl}/accept-invitation/${token}`;
      const company = await storage.getCompany(companyId);
      const inviterName = [currentUser.firstName, currentUser.lastName].filter(Boolean).join(" ") || currentUser.email;
      import("./email").then(({ sendInvitationEmail }) => {
        sendInvitationEmail({
          to: normalizedEmail,
          inviterName,
          companyName: company?.name || "your company",
          role,
          inviteUrl,
        }).catch((err) => console.error("[Invitation] Email send failed:", err));
      });

      res.status(201).json(invitation);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // List pending invitations for company (admin only)
  // @ts-ignore
  app.get("/api/invitations", requireAuth, async (req, res) => {
    try {
      const currentUser = (req as any).user;

      // Only global admins and company admins can list invitations
      if (currentUser.role !== "global_admin" && currentUser.role !== "company_admin") {
        return res.status(403).json({ error: "Insufficient permissions" });
      }

      // Company admins can only list invitations for their company
      const companyId = currentUser.role === "company_admin"
        ? currentUser.companyId
        : (req.query.companyId as string);

      if (!companyId) {
        return res.status(400).json({ error: "Company ID is required" });
      }

      const invitations = await storage.getPendingInvitations(companyId);
      res.json(invitations);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Revoke invitation (admin only)
  // @ts-ignore
  app.delete("/api/invitations/:id", requireAuth, async (req, res) => {
    try {
      const currentUser = (req as any).user;

      // Only global admins and company admins can revoke invitations
      if (currentUser.role !== "global_admin" && currentUser.role !== "company_admin") {
        return res.status(403).json({ error: "Insufficient permissions" });
      }

      // For company admins, verify they have a company ID
      if (currentUser.role === "company_admin" && !currentUser.companyId) {
        return res.status(403).json({ error: "Company admins must have a company ID" });
      }

      // Company admins can only revoke invitations for their company
      // Global admins can revoke any invitation (no company filter)
      const companyId = currentUser.role === "company_admin"
        ? currentUser.companyId
        : null; // null means no company filter (global admin)

      // @ts-ignore
      await storage.revokeInvitation(req.params.id, companyId);
      res.status(204).send();
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ============ OBJECT STORAGE (IMAGE UPLOADS) ============
  // Dual-mode: Replit object storage (when sidecar available) or local filesystem (VPS)
  const { LocalObjectStorageService, ObjectNotFoundError: LocalObjectNotFoundError, detectEnvironment } = await import("./localObjectStorage");
  const sharp = await import("sharp");

  const storageEnv = await detectEnvironment();
  let replitObjectStorage: any = null;
  let replitObjectAcl: any = null;

  if (storageEnv === "replit") {
    try {
      const replitStorage = await import("./objectStorage");
      const replitAcl = await import("./objectAcl");
      replitObjectStorage = replitStorage;
      replitObjectAcl = replitAcl;
      console.log("[Storage] Using Replit object storage");
    } catch (e) {
      console.warn("[Storage] Failed to load Replit object storage, falling back to local");
    }
  }

  const localStorageService = new LocalObjectStorageService();
  const useLocalStorage = !replitObjectStorage;

  if (useLocalStorage) {
    console.log("[Storage] Using local filesystem storage with company isolation");
  }

  const imageUpload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 20 * 1024 * 1024 },
    fileFilter: (_req, file, cb) => {
      if (file.mimetype.startsWith("image/") || file.mimetype === "application/pdf") {
        cb(null, true);
      } else {
        cb(new Error("Only image files and PDFs are allowed"));
      }
    },
  });

  app.get("/api/objects/status", requireAuth, async (req, res) => {
    try {
      if (useLocalStorage) {
        res.json({
          configured: true,
          mode: "local",
          uploadDir: process.env.UPLOAD_DIR || "./uploads",
        });
      } else {
        const objectStorageService = new replitObjectStorage.ObjectStorageService();
        const privateDir = objectStorageService.getPrivateObjectDir();
        const publicPaths = objectStorageService.getPublicObjectSearchPaths();
        res.json({
          configured: true,
          mode: "replit",
          privateDir,
          publicPaths,
        });
      }
    } catch (error: any) {
      res.status(500).json({ configured: false, error: error.message });
    }
  });

  // @ts-ignore
  app.post("/api/objects/upload", requireAuth, imageUpload.single("file"), async (req, res) => {
    try {
      if (useLocalStorage) {
        if (!req.file) {
          return res.status(400).json({ error: "No file uploaded" });
        }
        const companyId = (req as any).companyId;
        if (!companyId) {
          return res.status(400).json({ error: "Company context required for file uploads" });
        }
        const userId = (req as any).user?.id;
        const visibilityRaw = req.body?.visibility;
        const visibility: "public" | "private" = visibilityRaw === "public" ? "public" : "private";
        const normalizedUpload = await normalizeImageForStorage(
          req.file.buffer,
          req.file.mimetype,
          req.file.originalname,
        );
        const objectPath = await localStorageService.uploadFile(
          companyId,
          normalizedUpload.buffer,
          normalizedUpload.mimeType,
          visibility,
          userId
        );
        res.json({ uploadUrl: null, objectPath });
      } else {
        const objectStorageService = new replitObjectStorage.ObjectStorageService();
        const uploadURL = await objectStorageService.getObjectEntityUploadURL();
        res.json({ uploadUrl: uploadURL, requiresFinalize: true });
      }
    } catch (error: any) {
      if (error instanceof UnsupportedImageError) {
        return res.status(415).json({ error: error.message });
      }
      console.error("Error handling upload:", error);
      res.status(500).json({ error: "Failed to handle upload", details: error.message });
    }
  });

  /**
   * POST /api/objects/finalize
   * Claims an object that was uploaded through a signed PUT URL.
   * Normalizes HEIC/HEIF bytes to JPEG so every stored object is browser- and
   * scanner-compatible, then writes the ACL policy naming the caller as owner.
   * Only unclaimed objects (no ACL policy yet) can be finalized, so one user
   * cannot take ownership of another user's object.
   *
   * Handler logic lives in lib/finalizeHandler.ts (injectable deps) so it can
   * be integration-tested without importing the full routes module.
   */
  if (useLocalStorage) {
    app.post("/api/objects/finalize", requireAuth, (_req, res) => {
      res.status(400).json({ error: "Finalize is not used in local storage mode" });
    });
  } else {
    app.post(
      "/api/objects/finalize",
      requireAuth,
      createFinalizeHandler({
        normalizeObjectPath: (uploadUrl) => {
          const svc = new replitObjectStorage.ObjectStorageService();
          return svc.normalizeObjectEntityPath(uploadUrl);
        },
        getObjectFile: async (objectPath) => {
          const svc = new replitObjectStorage.ObjectStorageService();
          return svc.getObjectEntityFile(objectPath);
        },
        readMetadata: async (file: any) => {
          const [metadata] = await file.getMetadata();
          return {
            aclPolicyJson: metadata?.metadata?.[replitObjectAcl.ACL_POLICY_METADATA_KEY] ?? null,
            contentType: (metadata.contentType as string) || "application/octet-stream",
            metageneration: metadata.metageneration as string | number,
          };
        },
        readBytes: async (file: any) => {
          const chunks: Buffer[] = [];
          const stream = file.createReadStream();
          await new Promise<void>((resolve, reject) => {
            stream.on("data", (chunk: Buffer) => chunks.push(chunk));
            stream.on("end", resolve);
            stream.on("error", reject);
          });
          return Buffer.concat(chunks);
        },
        writeFile: async (file: any, bytes, contentType) => {
          await file.save(bytes, { contentType, resumable: false });
          const [savedMetadata] = await file.getMetadata();
          return { metageneration: savedMetadata.metageneration as string | number };
        },
        setAclPolicy: (file, policy, options) =>
          replitObjectAcl.setObjectAclPolicy(file, policy, options),
        isObjectNotFoundError: (err) =>
          replitObjectStorage && err instanceof replitObjectStorage.ObjectNotFoundError,
        isPreconditionFailedError: (err: any) => {
          const code = err?.code ?? err?.response?.status ?? err?.statusCode;
          return code === 412;
        },
      }),
    );
  }

  // @ts-ignore
  app.get("/objects/*objectPath", optionalAuth, async (req, res) => {
    const thumbnail = req.query.thumbnail === "true";

    try {
      if (useLocalStorage) {
        const user = (req as any).user;
        const userId = user?.id;
        let result;
        try {
          result = await localStorageService.getFilePublic(req.path);
        } catch {
          const companyId = (req as any).companyId;
          if (!companyId) {
            return res.sendStatus(userId ? 403 : 401);
          }
          result = await localStorageService.getFile(req.path, companyId);
        }

        const { filePath, metadata } = result;
        const companyIdForAccess = (req as any).companyId;
        if (!localStorageService.canAccessObject(metadata, userId, companyIdForAccess)) {
          return res.sendStatus(userId ? 403 : 401);
        }

        if (thumbnail) {
          const fs = await import("fs");
          res.set({
            "Content-Type": "image/jpeg",
            "Cache-Control": "public, max-age=31536000",
          });
          fs.createReadStream(filePath)
            .pipe(sharp.default().resize(200, 200, { fit: "cover" }).jpeg({ quality: 80 }))
            .pipe(res);
        } else {
          await localStorageService.downloadObject(filePath, metadata, res);
        }
      } else {
        const objectStorageService = new replitObjectStorage.ObjectStorageService();
        const objectFile = await objectStorageService.getObjectEntityFile(req.path);
        const user = (req as any).user;
        const userId = user?.id;
        const companyIdForAccess = (req as any).companyId;
        const canAccess = await objectStorageService.canAccessObjectEntity({
          objectFile,
          userId,
          companyId: companyIdForAccess,
          requestedPermission: replitObjectAcl.ObjectPermission.READ,
        });
        if (!canAccess) {
          return res.sendStatus(userId ? 403 : 401);
        }
        if (thumbnail) {
          const stream = objectFile.createReadStream();
          res.set({
            "Content-Type": "image/jpeg",
            "Cache-Control": "public, max-age=31536000",
          });
          stream
            .pipe(sharp.default().resize(200, 200, { fit: "cover" }).jpeg({ quality: 80 }))
            .pipe(res);
        } else {
          objectStorageService.downloadObject(objectFile, res);
        }
      }
    } catch (error) {
      console.error("Error serving image:", error);
      if (error instanceof LocalObjectNotFoundError || (replitObjectStorage && error instanceof replitObjectStorage.ObjectNotFoundError)) {
        return res.sendStatus(404);
      }
      return res.sendStatus(500);
    }
  });

