  // Get compatible units for a given unit (same kind: weight/volume/count)
  // @ts-ignore
  app.get("/api/units/compatible", requireAuth, async (req, res) => {
    const { unitId, inventoryItemId } = req.query as { unitId?: string; inventoryItemId?: string };
    
    if (!unitId || typeof unitId !== 'string') {
      return res.status(400).json({ error: "unitId query parameter is required" });
    }

    const companyId = (req as any).companyId;
    if (!companyId) {
      return res.status(401).json({ error: "Company ID required" });
    }

    // Get company to check unit system preference
    const company = await storage.getCompany(companyId);
    if (!company) {
      return res.status(404).json({ error: "Company not found" });
    }

    const [units, conversions] = await Promise.all([
      storage.getUnits(),
      storage.getUnitConversions(),
    ]);
    const targetUnit = units.find(u => u.id === unitId);
    
    if (!targetUnit) {
      return res.status(404).json({ error: "Unit not found" });
    }

    // Build a bidirectional adjacency list from unit_conversions
    const graph = new Map<string, Set<string>>();
    for (const conv of conversions) {
      if (!graph.has(conv.fromUnitId)) graph.set(conv.fromUnitId, new Set());
      if (!graph.has(conv.toUnitId)) graph.set(conv.toUnitId, new Set());
      graph.get(conv.fromUnitId)!.add(conv.toUnitId);
      graph.get(conv.toUnitId)!.add(conv.fromUnitId);
    }

    // BFS over the conversion graph to find all units reachable from the target
    const reachable = new Set<string>([targetUnit.id]);
    const queue: string[] = [targetUnit.id];
    while (queue.length > 0) {
      const current = queue.shift()!;
      for (const neighbor of (graph.get(current) || [])) {
        if (!reachable.has(neighbor)) {
          reachable.add(neighbor);
          queue.push(neighbor);
        }
      }
    }

    // Fractional pound units to exclude (can be entered in ounces instead)
    const fractionalPounds = ['eighth-pound', 'quarter-pound', 'half-pound'];

    // A unit is compatible if ALL of:
    // 1. Same kind as target (weight↔weight, volume↔volume, count↔count) OR
    //    cross-kind volume↔weight when an inventoryItemId context is present
    //    (water-density fallback: 1 mL ≈ 1 g — only valid for inventory items;
    //     recipe sub-components don't support density fallback)
    // 2. Not a fractional pound
    // 3. Reachable via graph OR toBaseRatio (same-kind); valid toBaseRatio (cross-kind)
    // 4. Matches company's preferred unit system
    const hasInventoryContext = Boolean(inventoryItemId && typeof inventoryItemId === 'string');
    const compatibleUnits = units.filter(u => {
      const sameKind = u.kind === targetUnit.kind;
      const crossKindWaterDensity =
        hasInventoryContext &&
        ((targetUnit.kind === "weight" && u.kind === "volume") ||
         (targetUnit.kind === "volume" && u.kind === "weight"));

      if (!sameKind && !crossKindWaterDensity) return false;
      if (fractionalPounds.includes(u.name)) return false;

      if (sameKind) {
        // Conversion-path check: allow if reachable via explicit graph edges OR
        // via the toBaseRatio transitive path (all same-kind units with valid ratios)
        const graphCompatible = reachable.has(u.id);
        const ratioCompatible = u.toBaseRatio > 0 && targetUnit.toBaseRatio > 0;
        if (!graphCompatible && !ratioCompatible) return false;
      } else {
        // Cross-kind: both sides must have valid toBaseRatio for the mL=g math to work
        if (u.toBaseRatio <= 0 || targetUnit.toBaseRatio <= 0) return false;
      }

      // Apply company's preferred unit system
      if (company.preferredUnitSystem === 'both' || !u.system) return true;
      return u.system === company.preferredUnitSystem;
    });

    // Per-item Recipe Unit whitelist: when an inventoryItemId is supplied,
    // check whether the item has explicitly configured recipe units.
    if (inventoryItemId && typeof inventoryItemId === 'string') {
      const item = await storage.getInventoryItem(inventoryItemId);
      if (item && item.companyId === companyId) {
        // storage.getInventoryItemUnits already orders by isIssueUnit then sortOrder.
        const perItem = await storage.getInventoryItemUnits(inventoryItemId);
        const unitById = new Map(units.map((u) => [u.id, u] as const));

        // Active recipe units: non-issue rows with a positive conversion factor.
        const activeRecipeRows = perItem.filter(
          (u) => u.isIssueUnit === 0 && u.unitsPerCanonical > 0
        );

        if (activeRecipeRows.length > 0) {
          // Restrict to base unit + explicitly configured recipe units only.
          // The "Show all" toggle in the UI is the escape hatch for anything else.
          const result = new Map<string, typeof units[number]>();
          const baseUnit = units.find(u => u.id === unitId);
          if (baseUnit) result.set(baseUnit.id, baseUnit);
          for (const row of activeRecipeRows) {
            const u = unitById.get(row.unitId);
            if (u) result.set(u.id, u);
          }
          return res.json(Array.from(result.values()));
        }

        // No active recipe units — fall back to full same-kind list with any
        // incomplete whitelist rows surfaced first (original behaviour).
        const recipeWhitelist = perItem.filter((u) => u.isIssueUnit === 0);
        const orderedWhitelistUnits = recipeWhitelist
          .map((row) => unitById.get(row.unitId))
          .filter((u): u is typeof units[number] => Boolean(u));
        const whitelistedIds = new Set(orderedWhitelistUnits.map((u) => u.id));
        const remaining = compatibleUnits.filter((u) => !whitelistedIds.has(u.id));
        return res.json([...orderedWhitelistUnits, ...remaining]);
      }
    }

    res.json(compatibleUnits);
  });

