  // GET /api/order-guides/warning-counts
  // Returns warning counts per vendorId for all pending_review order guides in the company.
  // Response: Record<vendorId, { warningCount: number; orderGuideId: string }>
  app.get("/api/order-guides/warning-counts", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { extractNameCount, hasNameCountSuspiciousRatio } = await import('./services/orderGuideProcessor');

      // Fetch all pending_review order guides for this company that have a vendorId
      const pendingGuides = await db
        .select()
        .from(orderGuides)
        .where(and(
          // @ts-ignore
          eq(orderGuides.companyId, companyId),
          // @ts-ignore
          eq(orderGuides.status, 'pending_review'),
        ));

      const result: Record<string, { warningCount: number; orderGuideId: string }> = {};

      for (const guide of pendingGuides) {
        if (!guide.vendorId) continue;

        const lines = await storage.getOrderGuideLines(guide.id);
        const warningCount = lines.filter(l =>
          hasNameCountSuspiciousRatio(extractNameCount(l.productName), l.caseSize)
        ).length;

        if (warningCount > 0) {
          // Keep the guide with the most warnings if multiple pending guides share a vendor
          const existing = result[guide.vendorId];
          if (!existing || warningCount > existing.warningCount) {
            result[guide.vendorId] = { warningCount, orderGuideId: guide.id };
          }
        }
      }

      return res.json(result);
    } catch (error: any) {
      console.error('[Order Guide Warning Counts Error]', error);
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * @swagger
   * /api/order-guides/{id}/review:
   *   get:
   *     summary: Get order guide for review
   *     description: Returns order guide with lines grouped by match status
   *     tags: [Order Guides]
   *     parameters:
   *       - in: path
   *         name: id
   *         required: true
   *         schema:
   *           type: string
   *     responses:
   *       200:
   *         description: Order guide with grouped matches
   */
  // @ts-ignore
  app.get("/api/order-guides/:id/review", requireAuth, async (req, res) => {
    try {
      const { id } = req.params;

      const { OrderGuideProcessor } = await import('./services/orderGuideProcessor');
      const processor = new OrderGuideProcessor(storage);

      // @ts-ignore
      const review = await processor.getForReview(id);
      res.json(review);
    } catch (error: any) {
      if (error.message === 'Order guide not found') {
        return res.status(404).json({ error: error.message });
      }
      console.error('[Order Guide Review Error]', error);
      res.status(500).json({ error: error.message });
    }
  });

  // PATCH /api/order-guides/:id/vendor — update vendor assignment on a pending_review guide
  app.patch("/api/order-guides/:id/vendor", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { id } = req.params;

      const bodySchema = z.object({
        vendorId: z.string().nullable(),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid request", details: parsed.error.errors });
      }
      const { vendorId } = parsed.data;

      // Verify guide exists and belongs to company
      // @ts-ignore
      const guide = await storage.getOrderGuide(id);
      if (!guide || guide.companyId !== companyId) {
        return res.status(404).json({ error: "Order guide not found." });
      }
      if (guide.status !== 'pending_review') {
        return res.status(409).json({ error: "Order guide has already been processed." });
      }

      // Validate vendorId belongs to company (if provided)
      if (vendorId) {
        const vendor = await storage.getVendor(vendorId, companyId);
        if (!vendor || vendor.companyId !== companyId) {
          return res.status(403).json({ error: "Vendor not found or access denied." });
        }
      }

      // @ts-ignore
      await storage.updateOrderGuideVendor(id, vendorId);

      // Sync order guide store assignments from vendor store assignments when setting a vendor.
      // If the vendor has store assignments, use those as the guide's target stores.
      // If vendorId is null or vendor has no store assignments, leave existing store assignments.
      if (vendorId) {
        const vendorStores = await storage.getVendorStores(vendorId);
        if (vendorStores.length > 0) {
          const storeIds = vendorStores.map(vs => vs.storeId);
          // @ts-ignore
          await storage.setOrderGuideStores(id, storeIds);
        }
      }

      return res.json({ success: true });
    } catch (error: any) {
      console.error('[Order Guide Vendor PATCH Error]', error);
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * @swagger
   * /api/order-guides/{id}/approve:
   *   post:
   *     summary: Approve order guide and create vendor items
   *     description: Create vendor_items for matched items and auto-create inventory items for selected new items
   *     tags: [Order Guides]
   *     parameters:
   *       - in: path
   *         name: id
   *         required: true
   *         schema:
   *           type: string
   *     requestBody:
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               importAll:
   *                 type: boolean
   *                 description: Import all items (overrides selectedLineIds)
   *               selectedLineIds:
   *                 type: array
   *                 items:
   *                   type: string
   *                 description: Array of line IDs to import
   *     responses:
   *       200:
   *         description: Order guide approved with counts of created items
   */
  // @ts-ignore
  app.post("/api/order-guides/:id/approve", requireAuth, async (req, res) => {
    try {
      const { id } = req.params;
      const companyId = (req as any).companyId;
      const sessionStoreId = (req as any).storeId;
      const userId = (req as any).userId;

      // Validate request body schema - now supports targetStoreIds for multi-store assignment
      const approvalSchema = z.object({
        importAll: z.boolean().optional(),
        selectedLineIds: z.array(z.string()).optional(),
        targetStoreIds: z.array(z.string()).optional(),
        /** Per-line unit overrides: lineId → unit name (e.g. "each", "pound", "ounce") */
        unitOverrides: z.record(z.string()).optional(),
        /** Per-line count overrides: lineId → count extracted from product name */
        countOverrides: z.record(z.number()).optional(),
        /** Per-line price-source overrides: lineId → 'unit' | 'case' (catch-weight reviewer toggle) */
        priceSourceOverrides: z.record(z.enum(['unit', 'case'])).optional(),
      }).refine(
        (data) => data.importAll === true || (data.selectedLineIds && data.selectedLineIds.length > 0),
        { message: 'Either importAll must be true or selectedLineIds must be a non-empty array' }
      );

      const validation = approvalSchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ 
          error: 'Invalid request body', 
          details: validation.error.errors 
        });
      }

      const { importAll, selectedLineIds, targetStoreIds, unitOverrides, countOverrides, priceSourceOverrides } = validation.data;

      // Determine target stores - use provided array, session store, or all company stores
      let storeIdsToAssign: string[] = [];
      if (targetStoreIds && targetStoreIds.length > 0) {
        // Validate that all target stores belong to this company
        const companyStores = await storage.getCompanyStores(companyId);
        const validStoreIds = new Set(companyStores.map(s => s.id));
        for (const storeId of targetStoreIds) {
          if (!validStoreIds.has(storeId)) {
            return res.status(400).json({ 
              error: `Store ${storeId} does not belong to your company` 
            });
          }
        }
        storeIdsToAssign = targetStoreIds;
      } else if (sessionStoreId) {
        storeIdsToAssign = [sessionStoreId];
      } else {
        // Default to all company stores
        const companyStores = await storage.getCompanyStores(companyId);
        if (companyStores.length > 0) {
          storeIdsToAssign = companyStores.map(s => s.id);
        } else {
          return res.status(400).json({ 
            error: 'No stores found for company. Please create a store first.' 
          });
        }
      }

      const { OrderGuideProcessor, extractNameCount, hasNameCountSuspiciousRatio } = await import('./services/orderGuideProcessor');
      const processor = new OrderGuideProcessor(storage);

      // Fetch guide + lines before approval (guide becomes non-pending_review after approve)
      // @ts-ignore
      const guideForEmail = await storage.getOrderGuide(id);
      // @ts-ignore
      const allLinesForEmail = await storage.getOrderGuideLines(id);

      const result = await processor.approve({
        // @ts-ignore
        orderGuideId: id,
        companyId,
        targetStoreIds: storeIdsToAssign,
        approvedBy: userId,
        importAll: importAll || false,
        selectedLineIds: selectedLineIds || [],
        unitOverrides: unitOverrides || {},
        countOverrides: countOverrides || {},
        priceSourceOverrides: priceSourceOverrides || {},
      });

      res.json(result);

      // Send import summary email non-blocking (best-effort)
      if (guideForEmail && userId) {
        import('./email').then(async ({ sendImportSummaryEmail }) => {
          try {
            const user = await storage.getUser(userId);
            if (!user?.email) return;

            // Identify which imported lines have suspicious name-count ratios
            const importedLineIds = new Set(
              importAll ? allLinesForEmail.map((l: any) => l.id) : (selectedLineIds || [])
            );
            const suspiciousLines = allLinesForEmail
              .filter((l: any) => importedLineIds.has(l.id))
              .map((l: any) => ({
                productName: l.productName,
                caseSize: l.caseSize,
                nameCount: extractNameCount(l.productName),
              }))
              .filter((l: { productName: string; caseSize: number | null; nameCount: number | null }) =>
                hasNameCountSuspiciousRatio(l.nameCount, l.caseSize)
              );

            let vendorName: string | null = null;
            if (guideForEmail.vendorId) {
              const vendors = await storage.getVendors(companyId);
              vendorName = vendors.find((v: any) => v.id === guideForEmail.vendorId)?.name ?? null;
            }

            await sendImportSummaryEmail({
              to: user.email,
              firstName: user.firstName || 'there',
              fileName: guideForEmail.fileName || 'Order guide',
              vendorName,
              vendorItemsCreated: result.vendorItemsCreated,
              inventoryItemsCreated: result.inventoryItemsCreated,
              suspiciousLines,
            });
          } catch (err) {
            console.error('[Order Guide] Import summary email failed:', err);
          }
        }).catch((err) => {
          console.error('[Order Guide] Failed to import email module:', err);
        });
      }
    } catch (error: any) {
      console.error('[Order Guide Approval Error]', error);
      // Determine appropriate HTTP status code
      let statusCode = 500;
      if (error.statusCode) {
        statusCode = error.statusCode; // Use custom status code if set
      } else if (error.message.includes('does not belong')) {
        statusCode = 403; // Authorization error
      } else if (error.message.includes('already been processed')) {
        statusCode = 409; // Conflict - resource state issue
      }
      res.status(statusCode).json({ error: error.message });
    }
  });

  // ===================================================================
  // AI-Powered CSV Inventory Import
  // ===================================================================

  /**
   * POST /api/inventory-import/analyze
   * Accepts raw CSV text and returns an AI-proposed column mapping.
   * Falls back to pattern-based detection if OpenAI is unavailable.
   */
  // @ts-ignore
  app.post("/api/inventory-import/analyze", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const { csvContent } = req.body;
      if (!csvContent || typeof csvContent !== 'string') {
        return res.status(400).json({ error: 'csvContent is required' });
      }

      const { analyzeColumns } = await import('./services/aiInventoryImporter');
      const proposal = await analyzeColumns(csvContent, {
        companyId: (req as any).companyId,
        userId: (req as any).user?.id ?? null,
      });
      res.json(proposal);
    } catch (error: any) {
      console.error('[Inventory Import Analyze]', error);
      res.status(500).json({ error: error.message });
    }
  });

  /**
   * POST /api/inventory-import/preview
   * Parses a CSV with the confirmed column mapping, runs fuzzy matching,
   * stores results as a generic order guide, and returns the guide ID + summary.
   */
  // @ts-ignore
  app.post("/api/inventory-import/preview", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const storeId = (req as any).storeId;

      const schema = z.object({
        csvContent: z.string(),
        columnMapping: z.object({
          productName: z.string(),
          vendorSku: z.string().optional().default(''),
          price: z.string().optional().default(''),
          caseSize: z.string().optional().default(''),
          innerPack: z.string().optional().default(''),
          unit: z.string().optional().default(''),
          category: z.string().optional().default(''),
          brand: z.string().optional().default(''),
          upc: z.string().optional().default(''),
          description: z.string().optional().default(''),
          variableWeight: z.string().optional().default(''),
        }),
        vendorId: z.string().nullable().optional(),
        fileName: z.string().optional(),
        useAiNormalization: z.boolean().optional().default(true),
      });

      const validation = schema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ error: 'Invalid request', details: validation.error.errors });
      }

      const { csvContent, columnMapping, vendorId, fileName, useAiNormalization } = validation.data;

      // SECURITY: Validate that vendorId (if provided) belongs to this company
      if (vendorId) {
        const companyVendors = await storage.getVendors(companyId);
        const validVendorIds = new Set(companyVendors.map((v: { id: string }) => v.id));
        if (!validVendorIds.has(vendorId)) {
          return res.status(403).json({ error: 'Vendor does not belong to your company' });
        }
      }

      // Extract product names for AI normalization (optional, gated behind flag)
      let canonicalNames: Map<string, string> | undefined;
      if (useAiNormalization) {
        try {
          // Parse CSV to extract product names
          const { parse: parseCsv } = await import('csv-parse/sync');
          const records = parseCsv(csvContent, {
            columns: true,
            skip_empty_lines: true,
            trim: true,
            bom: true,
          }) as Record<string, string>[];

          if (records.length > 0 && columnMapping.productName) {
            const rawNames = records
              .map(r => r[columnMapping.productName] || '')
              .filter(n => n.trim().length > 0);

            const { normalizeProductNames } = await import('./services/aiInventoryImporter');
            canonicalNames = await normalizeProductNames(rawNames, {
              companyId,
              userId: (req as any).user?.id ?? null,
            });
            console.log(`[Inventory Import] Normalized ${canonicalNames.size} product names via AI`);
          }
        } catch (normErr) {
          console.error('[Inventory Import] Name normalization failed (non-fatal):', normErr);
        }
      }

      const { OrderGuideProcessor } = await import('./services/orderGuideProcessor');
      const processor = new OrderGuideProcessor(storage);

      const result = await processor.processUpload({
        fileContent: csvContent,
        vendorKey: 'generic',
        vendorId: vendorId || null,
        companyId,
        storeId: storeId || '',
        fileName: fileName || 'inventory_import.csv',
        columnMapping: columnMapping,
        canonicalNames,
      });

      // Fetch the full review data so the client has everything for step 3
      const reviewData = await processor.getForReview(result.orderGuideId);

      // Enrich each line with canonical name from the in-memory normalization map
      // (canonical names are not persisted to DB — they live only during this preview session)
      if (canonicalNames && canonicalNames.size > 0) {
        const enrichLine = (line: Record<string, unknown>) => ({
          ...line,
          canonicalName: canonicalNames!.get(String(line.productName ?? '')) ?? null,
        });
        // @ts-ignore
        reviewData.lines.matched = reviewData.lines.matched.map(enrichLine);
        // @ts-ignore
        reviewData.lines.ambiguous = reviewData.lines.ambiguous.map(enrichLine);
        // @ts-ignore
        reviewData.lines.new = reviewData.lines.new.map(enrichLine);
      }

      res.json({
        orderGuideId: result.orderGuideId,
        summary: {
          total: result.totalItems,
          matched: result.highConfidenceMatches,
          ambiguous: result.mediumConfidenceMatches + result.lowConfidenceMatches,
          new: result.noMatches,
        },
        review: reviewData,
      });
    } catch (error: any) {
      console.error('[Inventory Import Preview]', error);
      res.status(500).json({ error: error.message });
    }
  });

  /**
   * POST /api/inventory-import/:id/approve
   * Approves the generic CSV import — creates inventory items, vendor items,
   * and store assignments. Delegates to OrderGuideProcessor.approve().
   */
  // @ts-ignore
  app.post("/api/inventory-import/:id/approve", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const { id } = req.params;
      const companyId = (req as any).companyId;
      const sessionStoreId = (req as any).storeId;
      const userId = (req as any).userId;

      const bodySchema = z.object({
        importAll: z.boolean().optional(),
        selectedLineIds: z.array(z.string()).optional(),
        targetStoreIds: z.array(z.string()).optional(),
        /** Per-line overrides: lineId → inventoryItemId or 'new' */
        lineOverrides: z.record(z.string()).optional(),
        /** Per-line vendor overrides: lineId → vendorId (overrides guide-level vendor) */
        vendorOverrides: z.record(z.string()).optional(),
      }).refine(
        (data) => data.importAll === true || (data.selectedLineIds && data.selectedLineIds.length > 0),
        { message: 'Either importAll must be true or selectedLineIds must be non-empty' }
      );

      const validation = bodySchema.safeParse(req.body);
      if (!validation.success) {
        return res.status(400).json({ error: 'Invalid request', details: validation.error.errors });
      }

      const { importAll, selectedLineIds, targetStoreIds, lineOverrides, vendorOverrides } = validation.data;

      let storeIdsToAssign: string[] = [];
      if (targetStoreIds && targetStoreIds.length > 0) {
        const companyStores = await storage.getCompanyStores(companyId);
        const validStoreIds = new Set(companyStores.map((s: any) => s.id));
        for (const sid of targetStoreIds) {
          if (!validStoreIds.has(sid)) {
            return res.status(400).json({ error: `Store ${sid} does not belong to your company` });
          }
        }
        storeIdsToAssign = targetStoreIds;
      } else if (sessionStoreId) {
        storeIdsToAssign = [sessionStoreId];
      } else {
        const companyStores = await storage.getCompanyStores(companyId);
        if (companyStores.length > 0) {
          storeIdsToAssign = companyStores.map((s: any) => s.id);
        } else {
          return res.status(400).json({ error: 'No stores found for company. Please create a store first.' });
        }
      }

      // SECURITY: Validate that any non-'new' lineOverride values are valid inventory item IDs
      // belonging to this company (prevents cross-tenant inventory linkage via ID injection)
      if (lineOverrides && Object.keys(lineOverrides).length > 0) {
        const nonNewOverrides = Object.values(lineOverrides).filter(v => v !== 'new');
        if (nonNewOverrides.length > 0) {
          const companyItems = await storage.getInventoryItems(undefined, undefined, companyId);
          const validItemIds = new Set(companyItems.map((item: { id: string }) => item.id));
          for (const itemId of nonNewOverrides) {
            if (!validItemIds.has(itemId)) {
              return res.status(403).json({ error: `Inventory item ${itemId} does not belong to your company` });
            }
          }
        }
      }

      // SECURITY: Validate that any per-row vendor overrides belong to this company
      // before passing them to the processor to prevent cross-tenant data injection
      if (vendorOverrides && Object.keys(vendorOverrides).length > 0) {
        const companyVendors = await storage.getVendors(companyId);
        const validVendorIds = new Set(companyVendors.map((v: { id: string }) => v.id));
        for (const [, vendorId] of Object.entries(vendorOverrides)) {
          if (!validVendorIds.has(vendorId)) {
            return res.status(403).json({ error: `Vendor ${vendorId} does not belong to your company` });
          }
        }
      }

      const { OrderGuideProcessor } = await import('./services/orderGuideProcessor');
      const processor = new OrderGuideProcessor(storage);

      const result = await processor.approve({
        // @ts-ignore
        orderGuideId: id,
        companyId,
        targetStoreIds: storeIdsToAssign,
        approvedBy: userId,
        importAll: importAll || false,
        selectedLineIds: selectedLineIds || [],
        lineOverrides: lineOverrides || {},
        vendorOverrides: vendorOverrides || {},
      });

      res.json(result);
    } catch (error: any) {
      console.error('[Inventory Import Approve]', error);
      let statusCode = 500;
      if (error.statusCode) statusCode = error.statusCode;
      else if (error.message?.includes('does not belong')) statusCode = 403;
      else if (error.message?.includes('already been processed')) statusCode = 409;
      res.status(statusCode).json({ error: error.message });
    }
  });

  // ===================================================================
  // AI-Powered Menu Image Scan Import
  // ===================================================================

  /** Helper: read image buffer from storage with company/user auth enforcement */
  async function readImageBuffer(
    objectPath: string,
    companyId: string,
    userId?: string,
  ): Promise<{ buffer: Buffer; mimeType: string }> {
    if (useLocalStorage) {
      // Local mode: getFile() resolves and validates the path belongs to companyId via prefix check
      const { filePath, metadata } = await localStorageService.getFile(objectPath, companyId);
      const fsModule = await import("fs");
      const buffer = fsModule.readFileSync(filePath);
      const mimeType = metadata.contentType || "image/jpeg";
      return { buffer, mimeType };
    } else {
      // Replit object storage: check ACL before reading.
      // Signed-PUT uploads track the requester's identity — canAccessObjectEntity enforces this.
      const objStorage = await import("./objectStorage");
      const svc = new objStorage.ObjectStorageService();
      const file = await svc.getObjectEntityFile(objectPath);

      const canAccess = await svc.canAccessObjectEntity({
        objectFile: file,
        userId,
        companyId,
        requestedPermission: replitObjectAcl.ObjectPermission.READ,
      });
      if (!canAccess) {
        const err: any = new Error("Access denied to requested object");
        err.status = 403;
        throw err;
      }

      const stream = file.createReadStream();
      const chunks: Buffer[] = [];
      await new Promise<void>((resolve, reject) => {
        stream.on("data", (chunk: Buffer) => chunks.push(chunk));
        stream.on("end", resolve);
        stream.on("error", reject);
      });
      const buffer = Buffer.concat(chunks);
      // Infer mime from path extension. Defaulting to image/jpeg is correct even
      // for a ".heic" object path: /api/objects/finalize converts HEIC bytes to
      // JPEG before the object is claimed, so stored bytes are already JPEG by
      // the time anything reads them. Every vision call site also re-detects the
      // format from the bytes, so this value is only a hint — don't "fix" it by
      // fetching stored metadata, which costs an extra round trip per read.
      const pathModule = await import("path");
      const ext = pathModule.extname(objectPath).toLowerCase().replace(".", "");
      const mimeMap: Record<string, string> = {
        jpg: "image/jpeg", jpeg: "image/jpeg",
        png: "image/png", webp: "image/webp", gif: "image/gif",
      };
      const mimeType = mimeMap[ext] || "image/jpeg";
      return { buffer, mimeType };
    }
  }

  /**
   * POST /api/menu-import/scan
   * Accepts an objectPath for an already-uploaded menu image.
   * Reads the file using the authorized storage service, calls GPT-4o Vision
   * to extract menu items, and either:
   *   - Creates a new session (default) and returns sessionId + items
   *   - Appends to an existing pending session when `sessionId` is provided
   *     (multi-page scanning: new items are merged onto the end of existing ones)
   */
  app.post("/api/menu-import/scan", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const bodySchema = z.object({
        imageObjectPath: z.string().min(1, "imageObjectPath is required"),
        storeId: z.string().optional(),
        sessionId: z.string().optional(), // present for multi-page append scans
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid request", details: parsed.error.errors });
      }
      const { imageObjectPath, storeId, sessionId: appendToSessionId } = parsed.data;
      const userId = (req as any).user?.id;
      const user = (req as any).user;

      // Validate storeId against accessible stores early to prevent unusable sessions
      if (storeId) {
        const accessibleStoreIds = await getAccessibleStores(user, companyId);
        if (!accessibleStoreIds.includes(storeId)) {
          return res.status(403).json({ error: "Store not accessible" });
        }
      }

      // When appending to an existing session, validate it first
      let existingSession: typeof menuImportSessions.$inferSelect | null = null;
      if (appendToSessionId) {
        const [found] = await db.select().from(menuImportSessions)
          .where(and(
            // @ts-ignore
            eq(menuImportSessions.id, appendToSessionId),
            // @ts-ignore
            eq(menuImportSessions.companyId, companyId),
          ));
        if (!found) return res.status(404).json({ error: "Session not found" });
        if (found.status !== "pending") return res.status(409).json({ error: "Session is no longer editable" });
        existingSession = found;
      }

      // Read the image buffer using the storage service (enforces company/user ownership)
      const { buffer } = await readImageBuffer(imageObjectPath, companyId, userId);
      let image;
      try {
        image = await normalizeImageForVision(buffer);
      } catch (error) {
        if (error instanceof UnsupportedImageError) return res.status(415).json({ error: error.message });
        throw error;
      }

      const { scanMenuImage } = await import('./services/menuScanner');
      const result = await scanMenuImage(image.buffer, image.mimeType, {
        companyId: (req as any).companyId,
        userId: (req as any).user?.id ?? null,
      });

      if (existingSession) {
        // Append mode: re-read extractedItems and re-validate status inside a transaction
        // immediately before writing. This eliminates two races:
        // 1. Stale-read: extractedItems may have changed via autosave PATCH during the scan.
        // 2. Status race: session may have been approved/cancelled during the 10-20s scan.
        let mergedItems: typeof result.items;
        try {
          // @ts-ignore
          mergedItems = await db.transaction(async (tx) => {
            const [fresh] = await tx.select({
              extractedItems: menuImportSessions.extractedItems,
              status: menuImportSessions.status,
            })
              .from(menuImportSessions)
              .where(and(
                // @ts-ignore
                eq(menuImportSessions.id, existingSession.id),
                // @ts-ignore
                eq(menuImportSessions.companyId, companyId),
              ));
            if (!fresh || fresh.status !== "pending") {
              throw Object.assign(new Error("Session is no longer editable"), { status: 409 });
            }
            const currentItems = fresh.extractedItems ?? [];
            const merged = [...currentItems, ...result.items];
            await tx.update(menuImportSessions)
              .set({ extractedItems: merged, updatedAt: new Date() })
              .where(and(
                // @ts-ignore
                eq(menuImportSessions.id, existingSession.id),
                // @ts-ignore
                eq(menuImportSessions.companyId, companyId),
                // @ts-ignore
                eq(menuImportSessions.status, "pending"),
              ));
            return merged;
          });
        } catch (txErr: any) {
          const code = txErr.status === 409 ? 409 : 500;
          return res.status(code).json({ error: txErr.message });
        }

        return res.json({
          sessionId: existingSession.id,
          items: mergedItems,
          newCount: result.items.length,
          count: mergedItems.length,
        });
      }

      // New session
      const [session] = await db.insert(menuImportSessions).values({
        companyId,
        storeId: storeId || null,
        status: "pending",
        rawImagePath: imageObjectPath,
        extractedItems: result.items,
      }).returning();

      return res.json({
        sessionId: session.id,
        items: result.items,
        newCount: result.items.length,
        count: result.items.length,
      });
    } catch (error: any) {
      console.error("[Menu Import Scan]", error);
      const status = error.status === 403 ? 403 : 500;
      return res.status(status).json({ error: error.message });
    }
  });

  /**
   * GET /api/menu-import/:sessionId
   * Returns the session and its extracted items.
   */
  app.get("/api/menu-import/:sessionId", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const [session] = await db.select().from(menuImportSessions)
        // @ts-ignore
        .where(and(eq(menuImportSessions.id, req.params.sessionId), eq(menuImportSessions.companyId, companyId)));
      if (!session) return res.status(404).json({ error: "Session not found" });
      return res.json({
        sessionId: session.id,
        status: session.status,
        items: session.extractedItems ?? [],
        disabledVariantGroupKeys: session.disabledVariantGroupKeys ?? [],
      });
    } catch (error: any) {
      console.error("[Menu Import GET]", error);
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * PATCH /api/menu-import/:sessionId
   * Persists user edits (edited/added/deleted rows) back to session staging data.
   * Called automatically as the user edits items in Step 2 (debounced autosave).
   */
  app.patch("/api/menu-import/:sessionId", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { sessionId } = req.params;

      const bodySchema = z.object({
        items: z.array(z.object({
          name: z.string(),
          description: z.string().optional().default(""),
          department: z.string().default(""),
          category: z.string().default(""),
          size: z.string().default(""),
          price: z.number().nullable().optional(),
        })),
        disabledVariantGroupKeys: z.array(z.string()).optional(),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid request", details: parsed.error.errors });
      }

      const [session] = await db.select().from(menuImportSessions)
        // @ts-ignore
        .where(and(eq(menuImportSessions.id, sessionId), eq(menuImportSessions.companyId, companyId)));
      if (!session) return res.status(404).json({ error: "Session not found" });
      if (session.status !== "pending") return res.status(409).json({ error: "Session is not editable" });

      const updatePayload: Record<string, any> = { extractedItems: parsed.data.items, updatedAt: new Date() };
      if (parsed.data.disabledVariantGroupKeys !== undefined) {
        updatePayload.disabledVariantGroupKeys = parsed.data.disabledVariantGroupKeys;
      }
      await db.update(menuImportSessions)
        .set(updatePayload)
        // @ts-ignore
        .where(eq(menuImportSessions.id, sessionId));

      return res.json({ success: true });
    } catch (error: any) {
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * POST /api/menu-import/:sessionId/approve
   * User-confirmed items → creates menu_items (with parent/variant structure for
   * multi-size items) + store_menu_items rows. Marks the session as approved.
   */
  app.post("/api/menu-import/:sessionId/approve", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { sessionId } = req.params;

      const bodySchema = z.object({
        items: z.array(z.object({
          name: z.string().min(1),
          description: z.string().optional().default(""),
          department: z.string().default(""),
          category: z.string().default(""),
          size: z.string().default(""),
          price: z.number().nullable().optional(),
          calorieCount: z.number().nullable().optional(),
        })),
        storeId: z.string().optional(),
        approvedVariantGroupKeys: z.array(z.string()).optional(),
      });

      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid request", details: parsed.error.errors });
      }

      const { items, approvedVariantGroupKeys } = parsed.data;
      const approvedGroupKeySet = approvedVariantGroupKeys ? new Set(approvedVariantGroupKeys) : null;

      // Verify session belongs to this company
      const [session] = await db.select().from(menuImportSessions)
        // @ts-ignore
        .where(and(eq(menuImportSessions.id, sessionId), eq(menuImportSessions.companyId, companyId)));
      if (!session) return res.status(404).json({ error: "Session not found" });
      if (session.status !== "pending") return res.status(409).json({ error: `Session cannot be approved (status: ${session.status})` });

      // Resolve storeId: prefer body param → session storeId → first accessible store
      const accessibleStoreIds = await getAccessibleStores((req as any).user, companyId);
      const accessibleIds = new Set(accessibleStoreIds);

      let resolvedStoreId = parsed.data.storeId || session.storeId || null;
      if (resolvedStoreId && !accessibleIds.has(resolvedStoreId)) {
        return res.status(403).json({ error: `Store ${resolvedStoreId} is not accessible` });
      }
      if (!resolvedStoreId && accessibleStoreIds.length > 0) {
        resolvedStoreId = accessibleStoreIds[0];
      }
      if (!resolvedStoreId) {
        return res.status(400).json({ error: "No accessible store found for this company" });
      }

      // Wrap in array for the insertion helpers below (single-store assignment)
      const targetStoreIds = [resolvedStoreId];

      // Compute groups before transaction so we can pass the count back
      type ItemGroup = { items: typeof items[number][], sortBase: number, groupKey: string };
      const groups = new Map<string, ItemGroup>();
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        const key = `${item.name.trim().toLowerCase()}|${(item.department||'').toLowerCase()}|${(item.category||'').toLowerCase()}`;
        if (!groups.has(key)) groups.set(key, { items: [], sortBase: i, groupKey: key });
        groups.get(key)!.items.push(item);
      }

      // Run all inserts and session update in a single transaction to prevent partial imports
      // @ts-ignore
      const { created, skipped, topLevelForSeeding } = await db.transaction(async (tx) => {
        const sizeIdCache = new Map<string, string>();
        const deptIdCache = new Map<string, string>();

        /** Find or create a menu_departments record within the transaction */
        async function findOrCreateDepartmentId(deptName: string): Promise<string> {
          const key = deptName.trim().toLowerCase();
          if (deptIdCache.has(key)) return deptIdCache.get(key)!;
          const [existing] = await tx.select().from(menuDepartments)
            // @ts-ignore
            .where(and(eq(menuDepartments.companyId, companyId), sql`lower(${menuDepartments.name}) = ${key}`));
          if (existing) { deptIdCache.set(key, existing.id); return existing.id; }
          const [newDept] = await tx.insert(menuDepartments).values({
            companyId, name: deptName.trim(), sortOrder: 0,
          }).onConflictDoNothing().returning();
          if (newDept) { deptIdCache.set(key, newDept.id); return newDept.id; }
          const [refetched] = await tx.select().from(menuDepartments)
            // @ts-ignore
            .where(and(eq(menuDepartments.companyId, companyId), sql`lower(${menuDepartments.name}) = ${key}`));
          deptIdCache.set(key, refetched.id);
          return refetched.id;
        }

        /** Find or create a menu_item_sizes record within the transaction */
        async function findOrCreateSizeId(sizeName: string): Promise<string> {
          const key = sizeName.trim().toLowerCase();
          if (sizeIdCache.has(key)) return sizeIdCache.get(key)!;

          const [existing] = await tx.select().from(menuItemSizes)
            // @ts-ignore
            .where(and(eq(menuItemSizes.name, sizeName.trim()), eq(menuItemSizes.companyId, companyId)));

          if (existing) {
            sizeIdCache.set(key, existing.id);
            return existing.id;
          }

          const [newSize] = await tx.insert(menuItemSizes).values({
            companyId,
            name: sizeName.trim(),
            sortOrder: 0,
            isDefault: 0,
            active: 1,
          }).onConflictDoNothing().returning();

          if (newSize) {
            sizeIdCache.set(key, newSize.id);
            return newSize.id;
          }

          // Race condition fallback — re-query within same tx
          const [refetched] = await tx.select().from(menuItemSizes)
            // @ts-ignore
            .where(and(eq(menuItemSizes.name, sizeName.trim()), eq(menuItemSizes.companyId, companyId)));
          sizeIdCache.set(key, refetched.id);
          return refetched.id;
        }

        /** Insert a menu_item row and assign to the target store within the transaction */
        async function insertMenuItemRow(values: {
          name: string; department: string | null; category: string | null;
          size: string | null; pluSku: string; price: number | null;
          sortOrder: number; parentMenuItemId?: string | null;
          menuItemSizeId?: string | null; menuDepartmentId?: string | null;
          description?: string | null; calorieCount?: number | null;
        }): Promise<string> {
          const [row] = await tx.insert(menuItems).values({
            companyId,
            name: values.name,
            department: values.department,
            category: values.category,
            size: values.size,
            pluSku: values.pluSku,
            parentMenuItemId: values.parentMenuItemId ?? null,
            menuItemSizeId: values.menuItemSizeId ?? null,
            isRecipeItem: 1,
            active: 1,
            price: values.price,
            sortOrder: values.sortOrder,
            menuDepartmentId: values.menuDepartmentId ?? null,
            description: values.description ?? null,
            calorieCount: values.calorieCount ?? null,
          }).returning();

          for (const sid of targetStoreIds) {
            await tx.insert(storeMenuItems).values({
              companyId,
              storeId: sid,
              menuItemId: row.id,
              active: 1,
            }).onConflictDoNothing();
          }
          return row.id;
        }

        const now = Date.now();
        let txCreated = 0;
        let pluCounter = 1;
        // Track descriptions for top-level items so we can seed recipes after the transaction
        const topLevelForSeeding: Array<{ id: string; name: string; description: string; price: number | null }> = [];

        for (const [, group] of groups) {
          const representative = group.items[0];
          // Only treat as multi-size variants when EVERY item has a non-empty size AND
          // there are at least 2 DISTINCT size values — this prevents duplicate rows
          // with the same size from being incorrectly modeled as parent+variant pairs.
          // If approvedGroupKeySet is provided, also require this group's key to be in it
          // (user opted in to auto-linking for this specific group).
          const nonEmptySizes = group.items.map(i => (i.size || '').trim()).filter(Boolean);
          const structurallyMultiSize = group.items.length > 1
            && nonEmptySizes.length === group.items.length
            && new Set(nonEmptySizes).size >= 2;
          const hasMultipleSizes = structurallyMultiSize
            && (approvedGroupKeySet === null || approvedGroupKeySet.has(group.groupKey));

          const deptName = (representative.department || '').trim() || 'Other';
          const menuDepartmentId = await findOrCreateDepartmentId(deptName);
          const representativeDescription = (representative as any).description?.trim() || '';

          if (hasMultipleSizes) {
            const parentPlu = `SCAN-${now}-${pluCounter++}`;
            const representativeCalories = (representative as any).calorieCount ?? null;
            const parentId = await insertMenuItemRow({
              name: representative.name.trim(),
              department: representative.department || null,
              category: representative.category || null,
              size: null,
              pluSku: parentPlu,
              price: null,
              sortOrder: group.sortBase,
              menuDepartmentId,
              description: representativeDescription || null,
              calorieCount: representativeCalories,
            });
            if (representativeDescription) {
              topLevelForSeeding.push({ id: parentId, name: representative.name.trim(), description: representativeDescription, price: null });
            }

            for (let j = 0; j < group.items.length; j++) {
              const variant = group.items[j];
              const variantPlu = `SCAN-${now}-${pluCounter++}`;
              const menuItemSizeId = variant.size ? await findOrCreateSizeId(variant.size) : null;
              await insertMenuItemRow({
                name: representative.name.trim(),
                department: representative.department || null,
                category: representative.category || null,
                size: variant.size || null,
                pluSku: variantPlu,
                price: variant.price ?? null,
                sortOrder: group.sortBase + j + 1,
                parentMenuItemId: parentId,
                menuItemSizeId,
                menuDepartmentId,
                calorieCount: (variant as any).calorieCount ?? null,
              });
              txCreated++;
            }
            txCreated++; // count the parent
          } else {
            // Import each item individually (preserves duplicate rows with same name/dept/cat
            // when they don't all have sizes — e.g., two distinct "Cheese Pizza" rows)
            for (let j = 0; j < group.items.length; j++) {
              const item = group.items[j];
              const pluSku = `SCAN-${now}-${pluCounter++}`;
              const itemDescription = (item as any).description?.trim() || representativeDescription;
              // Populate menuItemSizeId even for single items that have a size string
              const menuItemSizeId = item.size ? await findOrCreateSizeId(item.size) : null;
              const itemId = await insertMenuItemRow({
                name: item.name.trim(),
                department: item.department || null,
                category: item.category || null,
                size: item.size || null,
                pluSku,
                price: item.price ?? null,
                sortOrder: group.sortBase + j,
                menuItemSizeId,
                menuDepartmentId,
                description: itemDescription || null,
                calorieCount: (item as any).calorieCount ?? null,
              });
              if (itemDescription) {
                topLevelForSeeding.push({ id: itemId, name: item.name.trim(), description: itemDescription, price: item.price ?? null });
              }
              txCreated++;
            }
          }
        }

        // Mark session approved and clear staging data within the same transaction
        await tx.update(menuImportSessions)
          .set({ status: "approved", rawImagePath: null, extractedItems: null, updatedAt: new Date() })
          // @ts-ignore
          .where(eq(menuImportSessions.id, sessionId));

        return { created: txCreated, skipped: 0, topLevelForSeeding };
      });

      // Seed recipe stubs for items that have a description (non-fatal if this fails)
      let recipesSeeded = 0;
      if (topLevelForSeeding.length > 0) {
        try {
          const { seedRecipesFromDescriptions } = await import('./services/menuRecipeSeeder');
          const seeded = await seedRecipesFromDescriptions(topLevelForSeeding, companyId);
          recipesSeeded = seeded.length;
        } catch (seedErr) {
          console.error("[Menu Import Approve] Recipe seeding failed (non-fatal):", seedErr);
        }
      }

      return res.json({ menuItemsCreated: created, skipped, recipesSeeded });
    } catch (error: any) {
      console.error("[Menu Import Approve]", error);
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * DELETE /api/menu-import/:sessionId
   * Cancels/cleans up a pending session.
   */
  app.delete("/api/menu-import/:sessionId", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      // Only cancel sessions that are still pending (preserve audit integrity for approved/cancelled)
      const result = await db.update(menuImportSessions)
        .set({
          status: "cancelled",
          rawImagePath: null,
          extractedItems: null,
          updatedAt: new Date(),
        })
        .where(and(
          // @ts-ignore
          eq(menuImportSessions.id, req.params.sessionId),
          // @ts-ignore
          eq(menuImportSessions.companyId, companyId),
          // @ts-ignore
          eq(menuImportSessions.status, "pending"),
        ))
        .returning({ id: menuImportSessions.id });
      if (result.length === 0) {
        // Session not found, already approved/cancelled — treat as success (idempotent cleanup)
        return res.json({ success: true });
      }
      return res.json({ success: true });
    } catch (error: any) {
      return res.status(500).json({ error: error.message });
    }
  });

  // ============================================================
  // RECIPE IMPORT — AI recipe image scan wizard
  // ============================================================

  /**
   * POST /api/recipe-import/scan
   * Upload image → GPT-4o extracts recipe name/yield/ingredients → fuzzy-match inventory → create session
   */
  app.post("/api/recipe-import/scan", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const userId = (req as any).user?.id;

      const bodySchema = z.object({
        imageObjectPath: z.string().min(1),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "imageObjectPath is required" });
      }
      const { imageObjectPath } = parsed.data;

      // Read only after authorization, then normalize iPhone HEIC/HEIF for the vision service.
      const { buffer } = await readImageBuffer(imageObjectPath, companyId, userId);
      let image;
      try {
        image = await normalizeImageForVision(buffer);
      } catch (error) {
        if (error instanceof UnsupportedImageError) return res.status(415).json({ error: error.message });
        throw error;
      }

      // Run AI extraction
      const { scanRecipeImage } = await import('./services/recipeScanner');
      const scan = await scanRecipeImage(image.buffer, image.mimeType, { companyId, userId: userId ?? null });

      // Fuzzy-match ingredients: preload inventory + categories once, then match in-process (O(1) DB round-trips)
      const { ItemMatcher } = await import('./services/itemMatcher');
      const matcher = new ItemMatcher(storage);

      const [inventoryItems, categories] = await Promise.all([
        storage.getInventoryItems(undefined, undefined, companyId),
        storage.getCategories(companyId),
      ]);

      const vendorProducts = scan.ingredients.map((ing, i) => ({
        vendorSku: `scan-${i}`,
        vendorProductName: ing.name,
      }));
      const batchResults = matcher.matchWithPreloadedData(vendorProducts, inventoryItems, categories);

      const matchedIngredients = scan.ingredients.map((ing, i) => {
        const result = batchResults.get(`scan-${i}`) ?? {
          inventoryItemId: null, inventoryItemName: null, confidence: 'none' as const, score: 0, matchReason: '',
        };
        return {
          name: ing.name,
          qty: ing.qty,
          unit: ing.unit,
          inventoryItemId: result.confidence !== 'none' ? result.inventoryItemId : null,
          inventoryItemName: result.confidence !== 'none' ? result.inventoryItemName : null,
          matchConfidence: result.confidence,
          include: true, // All ingredients included by default; unmatched ones become missing-item placeholders
        };
      });

      // Create session
      const [session] = await db.insert(recipeImportSessions).values({
        companyId,
        status: "pending",
        rawImagePath: imageObjectPath,
        extractedData: {
          recipeName: scan.recipeName,
          yieldQty: scan.yieldQty,
          yieldUnit: scan.yieldUnit,
          ingredients: matchedIngredients,
          instructions: scan.instructions ?? null,
        },
      }).returning();

      return res.json({
        sessionId: session.id,
        recipeName: scan.recipeName,
        yieldQty: scan.yieldQty,
        yieldUnit: scan.yieldUnit,
        ingredients: matchedIngredients,
        instructions: scan.instructions ?? null,
      });
    } catch (error: any) {
      console.error("[Recipe Import Scan]", error);
      const status = error.status === 403 ? 403 : 500;
      return res.status(status).json({ error: error.message });
    }
  });

  /**
   * GET /api/recipe-import/:sessionId
   * Returns session data for URL-based rehydration.
   * Returns 409 if session is already approved (non-re-enterable).
   */
  app.get("/api/recipe-import/:sessionId", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const [session] = await db.select().from(recipeImportSessions)
        // @ts-ignore
        .where(and(eq(recipeImportSessions.id, req.params.sessionId), eq(recipeImportSessions.companyId, companyId)));
      if (!session) return res.status(404).json({ error: "Session not found" });
      if (session.status === "approved") {
        return res.json({ status: "approved", recipeId: session.recipeId || null });
      }
      return res.json({
        sessionId: session.id,
        status: session.status,
        ...(session.extractedData || {}),
      });
    } catch (error: any) {
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * PATCH /api/recipe-import/:sessionId
   * Persists user edits back to the session's extractedData (staged state).
   * Only allowed on pending sessions.
   */
  app.patch("/api/recipe-import/:sessionId", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { sessionId } = req.params;

      const ingredientSchema = z.object({
        name: z.string(),
        qty: z.number(),
        unit: z.string(),
        inventoryItemId: z.string().nullable(),
        inventoryItemName: z.string().nullable(),
        matchConfidence: z.enum(["high", "medium", "low", "none"]),
        include: z.boolean(),
      });
      const bodySchema = z.object({
        recipeName: z.string().min(1),
        yieldQty: z.number().positive(),
        yieldUnit: z.string().min(1),
        canBeIngredient: z.number().int().min(0).max(1).default(0),
        ingredients: z.array(ingredientSchema),
        instructions: z.string().optional(),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid request", details: parsed.error.errors });
      }

      const [session] = await db.select().from(recipeImportSessions)
        // @ts-ignore
        .where(and(eq(recipeImportSessions.id, sessionId), eq(recipeImportSessions.companyId, companyId)));
      if (!session) return res.status(404).json({ error: "Session not found" });
      if (session.status !== "pending") {
        return res.status(409).json({ error: `Session cannot be edited (status: ${session.status})` });
      }

      await db.update(recipeImportSessions)
        .set({
          extractedData: {
            recipeName: parsed.data.recipeName,
            yieldQty: parsed.data.yieldQty,
            yieldUnit: parsed.data.yieldUnit,
            canBeIngredient: parsed.data.canBeIngredient,
            ingredients: parsed.data.ingredients,
            instructions: parsed.data.instructions ?? null,
          },
          updatedAt: new Date(),
        })
        // @ts-ignore
        .where(eq(recipeImportSessions.id, sessionId));

      return res.json({ ok: true });
    } catch (error: any) {
      console.error("[Recipe Import PATCH]", error);
      return res.status(500).json({ error: error.message });
    }
  });

  /**
   * POST /api/recipe-import/:sessionId/approve
   * Creates a recipe + recipe_components from user-confirmed data.
   * Body: { recipeName, yieldQty, yieldUnit, canBeIngredient?, ingredients: [{ name, qty, unit, inventoryItemId, include }] }
   */
  app.post("/api/recipe-import/:sessionId/approve", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { sessionId } = req.params;

      const ingredientSchema = z.object({
        name: z.string(),
        qty: z.number().positive(),
        unit: z.string(),
        inventoryItemId: z.string().nullable(),
        include: z.boolean(),
      });
      const bodySchema = z.object({
        recipeName: z.string().min(1),
        yieldQty: z.number().positive(),
        yieldUnit: z.string().min(1),
        canBeIngredient: z.number().int().min(0).max(1).default(0),
        ingredients: z.array(ingredientSchema),
        instructions: z.string().optional(),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "Invalid request", details: parsed.error.errors });
      }

      // Verify session
      const [session] = await db.select().from(recipeImportSessions)
        // @ts-ignore
        .where(and(eq(recipeImportSessions.id, sessionId), eq(recipeImportSessions.companyId, companyId)));
      if (!session) return res.status(404).json({ error: "Session not found" });

      // Idempotent: if already approved and recipe exists, return the recipe info
      if (session.status === "approved" && session.recipeId) {
        const [existingRecipe] = await db.select().from(recipes)
          // @ts-ignore
          .where(and(eq(recipes.id, session.recipeId), eq(recipes.companyId, companyId)));
        if (existingRecipe) {
          return res.json({
            recipeId: existingRecipe.id,
            recipeName: existingRecipe.name,
            componentsCreated: 0,
            skippedIngredients: 0,
            alreadyApproved: true,
          });
        }
      }
      if (session.status !== "pending") return res.status(409).json({ error: `Session cannot be approved (status: ${session.status})` });

      // Resolve units
      const allUnits = await storage.getUnits();
      function resolveUnitId(unitText: string): string | null {
        const u = unitText.toLowerCase().trim();
        // Exact match on name or abbreviation
        let found = allUnits.find(unit =>
          unit.name.toLowerCase() === u ||
          (unit.abbreviation && unit.abbreviation.toLowerCase() === u)
        );
        if (!found) {
          // Substring match
          found = allUnits.find(unit =>
            unit.name.toLowerCase().includes(u) ||
            u.includes(unit.name.toLowerCase())
          );
        }
        return found?.id || null;
      }

      const yieldUnitId = resolveUnitId(parsed.data.yieldUnit);
      const eachUnit = allUnits.find(u => u.name.toLowerCase() === 'each' || u.abbreviation?.toLowerCase() === 'ea');
      const resolvedYieldUnitId: string = yieldUnitId ?? eachUnit?.id ?? allUnits[0]?.id;
      if (!resolvedYieldUnitId) {
        return res.status(400).json({ error: `Cannot resolve yield unit: ${parsed.data.yieldUnit}` });
      }

      // Split: matched ingredients get real components; unmatched-but-included get placeholder components
      const matchedIngredients = parsed.data.ingredients.filter(
        (ing) => ing.include && ing.inventoryItemId
      );
      const unmatchedIncluded = parsed.data.ingredients.filter(
        (ing) => ing.include && !ing.inventoryItemId
      );

      // Validate ownership of all referenced inventory items
      if (matchedIngredients.length > 0) {
        const itemIds = matchedIngredients.map(i => i.inventoryItemId!);
        const validItems = await db.select({ id: inventoryItems.id }).from(inventoryItems)
          // @ts-ignore
          .where(and(inArray(inventoryItems.id, itemIds), eq(inventoryItems.companyId, companyId)));
        // @ts-ignore
        const validIds = new Set(validItems.map(i => i.id));
        const invalid = itemIds.find(id => !validIds.has(id));
        if (invalid) return res.status(403).json({ error: `Inventory item ${invalid} does not belong to your company` });
      }

      // Create the recipe and components in a transaction
      // @ts-ignore
      const recipe = await db.transaction(async (tx) => {
        // Create recipe
        const [newRecipe] = await tx.insert(recipes).values({
          companyId,
          name: parsed.data.recipeName,
          yieldQty: parsed.data.yieldQty,
          yieldUnitId: resolvedYieldUnitId,
          computedCost: 0,
          canBeIngredient: parsed.data.canBeIngredient,
          isActive: 1,
          instructions: parsed.data.instructions || null,
          // Carry the scanned photo over as the recipe image (only set if not already provided)
          imagePath: session.rawImagePath ?? null,
        }).returning();

        // Create recipe components for matched ingredients
        let sortOrder = 0;
        for (const ing of matchedIngredients) {
          const unitId = resolveUnitId(ing.unit) || resolvedYieldUnitId;
          await tx.insert(recipeComponents).values({
            recipeId: newRecipe.id,
            componentType: 'inventory_item',
            componentId: ing.inventoryItemId!,
            qty: ing.qty,
            unitId,
            sortOrder: sortOrder++,
          });
        }

        // Create placeholder components for unmatched-but-included ingredients
        // componentId is a random UUID that won't exist in inventory_items — system detects as missingItem:true
        // missingItemName stores the display name so the recipe builder shows it correctly
        for (const ing of unmatchedIncluded) {
          const unitId = resolveUnitId(ing.unit) || resolvedYieldUnitId;
          await tx.insert(recipeComponents).values({
            recipeId: newRecipe.id,
            componentType: 'inventory_item',
            componentId: crypto.randomUUID(),
            qty: ing.qty,
            unitId,
            sortOrder: sortOrder++,
            missingItemName: ing.name,
          });
        }

        // Mark session approved, store recipeId for idempotent retries, clear staging payload
        await tx.update(recipeImportSessions)
          .set({ status: "approved", recipeId: newRecipe.id, extractedData: null, rawImagePath: null, updatedAt: new Date() })
          // @ts-ignore
          .where(eq(recipeImportSessions.id, sessionId));

        return newRecipe;
      });

      // Calculate and update computed cost (outside transaction so it reads committed data)
      try {
        const cost = await calculateRecipeCost(recipe.id);
        await storage.updateRecipe(recipe.id, { computedCost: cost });
      } catch (costErr) {
        console.error("[Recipe Import] Cost calculation failed (non-fatal):", costErr);
      }

      // AI-crop the food dish photo from the scanned recipe card (non-blocking)
      let photoCropped = false;
      if (session.rawImagePath) {
        try {
          const { cropFoodPhotoFromScan } = await import("./services/recipePhotoCropper");
          const userId = (req as any).user?.id ?? "server";
          // Read through the authorized helper and normalize (HEIC/HEIF -> JPEG)
          // before the cropper sends anything to vision.
          const rawScan = await readImageBuffer(
            session.rawImagePath,
            (req as any).companyId,
            (req as any).user?.id,
          );
          const normalizedScan = await normalizeImageForVision(rawScan.buffer);
          const cropResult = await cropFoodPhotoFromScan(normalizedScan, userId, {
            companyId: (req as any).companyId,
            userId: (req as any).user?.id ?? null,
          });
          if (cropResult.croppedPath) {
            await db.update(recipes)
              .set({ imagePath: cropResult.croppedPath, sourceImagePath: session.rawImagePath })
              // @ts-ignore
              .where(eq(recipes.id, recipe.id));
            photoCropped = true;
          }
        } catch (cropErr) {
          console.error("[Recipe Import] Photo crop failed (non-fatal):", cropErr);
        }
      }

      // Unmatched count = placeholder components created (visible in recipe builder as missing items)
      const skippedCount = unmatchedIncluded.length;

      return res.json({
        recipeId: recipe.id,
        recipeName: recipe.name,
        componentsCreated: matchedIngredients.length,
        skippedIngredients: skippedCount,
        photoCropped,
      });
    } catch (error: any) {
      console.error("[Recipe Import Approve]", error);
      return res.status(500).json({ error: error.message });
    }
  });

