  // Extract step-by-step instructions from a recipe image using GPT-4o Vision
  // @ts-ignore
  app.post("/api/recipes/extract-instructions", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const userId = (req as any).user?.id;

      const bodySchema = z.object({
        objectPath: z.string().min(1, "objectPath is required"),
      });
      const parsed = bodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: "objectPath is required" });
      }

      const { buffer } = await readImageBuffer(parsed.data.objectPath, companyId, userId);
      let image;
      try {
        image = await normalizeImageForVision(buffer);
      } catch (error) {
        if (error instanceof UnsupportedImageError) return res.status(415).json({ error: error.message });
        throw error;
      }

      const { extractRecipeInstructions } = await import('./services/recipeScanner');
      const instructions = await extractRecipeInstructions(image.buffer, image.mimeType, { companyId, userId: userId ?? null });

      res.json({ instructions });
    } catch (error: any) {
      console.error("extract-instructions error:", error);
      res.status(500).json({ error: error.message || "Failed to extract instructions" });
    }
  });

