  // ============ INVENTORY COUNTS ============
  // @ts-ignore
  app.get("/api/inventory-counts", requireAuth, async (req, res) => {
    const companyId = (req as any).companyId as string | undefined;
    if (!companyId) {
      return res.status(401).json({ error: "Unauthorized" });
    }
    const storeId = req.query.storeId as string | undefined;
    const storageLocationId = req.query.storageLocationId as string | undefined;
    const counts = await storage.getInventoryCounts(companyId, storeId, storageLocationId);
    
    // Enrich counts with store information
    // Get unique company IDs from counts to fetch all relevant stores
    const companyIds = [...new Set(counts.map(c => c.companyId))];
    const allStores = await Promise.all(
      companyIds.map(id => storage.getCompanyStores(id))
    );
    const storesMap = new Map(allStores.flat().map(s => [s.id, s]));

    // Resolve userId → user full name, grouped by companyId for tenant isolation
    const usersByCompany = new Map<string, Map<string, { id: string; firstName: string; lastName: string; fullName: string }>>();
    for (const cid of companyIds) {
      const userIds = counts
        .filter(c => c.companyId === cid && c.userId && c.userId !== "system")
        .map(c => c.userId);
      const userMap = await storage.getUsersByIds(userIds, cid);
      usersByCompany.set(cid, userMap);
    }
    
    // Fetch progress (countedItems / totalItems) for all sessions in one query
    const countIds = counts.map(c => c.id);
    const progressData = await storage.getInventoryCountProgressBatch(countIds);
    const progressMap = new Map(progressData.map(p => [p.countId, p]));

    const enrichedCounts = counts.map(count => {
      const store = storesMap.get(count.storeId);
      const userMap = usersByCompany.get(count.companyId);
      const resolvedUser = userMap?.get(count.userId);
      const userName = resolvedUser
        ? resolvedUser.fullName
        : count.userId === "system"
          ? "System"
          : count.userId || "Unknown";
      const progress = progressMap.get(count.id);
      return {
        ...count,
        storeName: store?.name || 'Unknown Store',
        userName,
        countedItems: progress?.countedItems ?? 0,
        totalItems: progress?.totalItems ?? 0,
      };
    });
    
    res.json(enrichedCounts);
  });

  // Lightweight summary of the most recent applied count — no tier gate, used on Analyze landing for all tiers
  app.get("/api/inventory-counts/recent-summary", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId as string | undefined;
      if (!companyId) {
        return res.status(401).json({ error: "Unauthorized" });
      }
      const { storeId } = req.query;
      if (!storeId) {
        return res.status(400).json({ error: "Missing required parameter: storeId" });
      }

      // Verify store belongs to company (multi-tenant isolation)
      const store = await storage.getCompanyStore(storeId as string, companyId);
      if (!store) {
        return res.status(403).json({ error: "Store not found or access denied" });
      }

      // Get all applied counts for this store, sorted newest first
      const allCounts = await db.query.inventoryCounts.findMany({
        where: and(
          // @ts-ignore
          eq(inventoryCounts.companyId, companyId),
          // @ts-ignore
          eq(inventoryCounts.storeId, storeId as string),
          // @ts-ignore
          eq(inventoryCounts.applied, 1)
        ),
      });

      if (allCounts.length === 0) {
        return res.json(null);
      }

      const sorted = allCounts.sort(
        // @ts-ignore
        (a, b) => new Date(b.countDate).getTime() - new Date(a.countDate).getTime()
      );

      const currentCount = sorted[0];
      const previousCount = sorted[1] ?? null;

      // Aggregate current count lines
      const currentLines = await db.query.inventoryCountLines.findMany({
        // @ts-ignore
        where: eq(inventoryCountLines.inventoryCountId, currentCount.id),
      });

      // @ts-ignore
      const totalItems = new Set(currentLines.map(l => l.inventoryItemId)).size;
      // @ts-ignore
      const totalValue = currentLines.reduce((sum, l) => sum + l.qty * (l.unitCost ?? 0), 0);

      // Previous count value (for delta)
      let previousValue: number | null = null;
      if (previousCount) {
        const previousLines = await db.query.inventoryCountLines.findMany({
          // @ts-ignore
          where: eq(inventoryCountLines.inventoryCountId, previousCount.id),
        });
        // @ts-ignore
        previousValue = previousLines.reduce((sum, l) => sum + l.qty * (l.unitCost ?? 0), 0);
      }

      return res.json({
        countId: currentCount.id,
        countDate: currentCount.countDate,
        totalItems,
        totalValue,
        previousValue,
        valueDelta: previousValue !== null ? totalValue - previousValue : null,
      });
    } catch (error: any) {
      console.error("recent-summary error:", error);
      return res.status(500).json({ error: "Failed to fetch recent count summary" });
    }
  });

