  // Initialize zero baseline - creates a completed inventory count session with all items at zero
  // This establishes a starting point for new stores that haven't done a physical count yet
  // @ts-ignore
  app.post("/api/inventory-counts/initialize-baseline", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const user = (req as any).user;
      const { storeId } = req.body;

      if (!storeId) {
        return res.status(400).json({ error: "Store ID is required" });
      }

      // Verify store belongs to company
      const store = await storage.getCompanyStore(storeId, companyId);
      if (!store) {
        return res.status(404).json({ error: "Store not found" });
      }

      // Check if any applied inventory count already exists for this store
      const existingCounts = await storage.getInventoryCounts(companyId, storeId);
      const appliedCounts = existingCounts.filter((c: any) => c.applied === 1);
      if (appliedCounts.length > 0) {
        return res.status(400).json({ 
          error: "This store already has completed inventory counts. Zero baseline is only for new stores." 
        });
      }

      // Get all active inventory items for this store
      const activeItemsQuery = await db
        .select({ inventoryItem: inventoryItems })
        .from(inventoryItems)
        .innerJoin(
          storeInventoryItems,
          and(
            // @ts-ignore
            eq(storeInventoryItems.inventoryItemId, inventoryItems.id),
            // @ts-ignore
            eq(storeInventoryItems.storeId, storeId)
          )
        )
        .where(
          and(
            // @ts-ignore
            eq(inventoryItems.companyId, companyId),
            // @ts-ignore
            eq(inventoryItems.active, 1),
            // @ts-ignore
            eq(storeInventoryItems.active, 1)
          )
        );

      // @ts-ignore
      const activeItems = activeItemsQuery.map(row => row.inventoryItem);

      if (activeItems.length === 0) {
        return res.status(400).json({ error: "No active inventory items found for this store" });
      }

      // Get storage locations for items
      // @ts-ignore
      const itemIds = activeItems.map(item => item.id);
      const itemLocationsQuery = await db
        .select({
          inventoryItemId: inventoryItemLocations.inventoryItemId,
          storageLocationId: inventoryItemLocations.storageLocationId,
        })
        .from(inventoryItemLocations)
        .innerJoin(
          storageLocations,
          // @ts-ignore
          eq(inventoryItemLocations.storageLocationId, storageLocations.id)
        )
        .where(
          and(
            // @ts-ignore
            inArray(inventoryItemLocations.inventoryItemId, itemIds),
            // @ts-ignore
            eq(storageLocations.companyId, companyId)
          )
        );

      const itemLocationsMap = new Map<string, string[]>();
      for (const location of itemLocationsQuery) {
        const existing = itemLocationsMap.get(location.inventoryItemId) || [];
        existing.push(location.storageLocationId);
        itemLocationsMap.set(location.inventoryItemId, existing);
      }

      // Create the baseline inventory count session
      const today = new Date();
      const countDate = new Date(Date.UTC(today.getFullYear(), today.getMonth(), today.getDate()));
      
      const baselineCount = await storage.createInventoryCount({
        companyId,
        storeId,
        countDate,
        // @ts-ignore
        notes: "System-generated zero baseline for new store initialization",
        userId: user.id,
        isPowerSession: 0,
      });

      // Create count lines with qty = 0 for all items
      const baselineCompany = await storage.getCompany(companyId);
      let linesCreated = 0;
      for (const item of activeItems) {
        const locations = itemLocationsMap.get(item.id) || [];
        
        if (locations.length === 0) continue;

        for (const storageLocationId of locations) {
          await storage.createInventoryCountLine({
            inventoryCountId: baselineCount.id,
            inventoryItemId: item.id,
            storageLocationId,
            qty: 0,
            unitId: item.unitId,
            unitCost: getEffectiveUnitCost(item, baselineCompany),
            userId: user.id,
          });
          linesCreated++;
        }
      }

      // Apply the count immediately (set all on-hand quantities to 0)
      await withTransaction(async (tx) => {
        for (const item of activeItems) {
          const [existingStoreItem] = await tx
            .select()
            // @ts-ignore
            .from(storeInventoryItems)
            .where(
              and(
                // @ts-ignore
                eq(storeInventoryItems.companyId, companyId),
                // @ts-ignore
                eq(storeInventoryItems.storeId, storeId),
                // @ts-ignore
                eq(storeInventoryItems.inventoryItemId, item.id)
              )
            )
            .limit(1);
          
          if (existingStoreItem) {
            await tx
              // @ts-ignore
              .update(storeInventoryItems)
              .set({ 
                onHandQty: 0,
                updatedAt: new Date()
              })
              .where(
                and(
                  // @ts-ignore
                  eq(storeInventoryItems.companyId, companyId),
                  // @ts-ignore
                  eq(storeInventoryItems.storeId, storeId),
                  // @ts-ignore
                  eq(storeInventoryItems.inventoryItemId, item.id)
                )
              );
          }
        }

        // Mark count as applied
        await tx
          // @ts-ignore
          .update(inventoryCounts)
          .set({ 
            applied: 1,
            appliedAt: new Date(),
            appliedBy: user.id
          })
          .where(
            and(
              // @ts-ignore
              eq(inventoryCounts.id, baselineCount.id),
              // @ts-ignore
              eq(inventoryCounts.companyId, companyId)
            )
          );
      });

      res.status(201).json({
        message: `Zero baseline initialized for ${activeItems.length} inventory items`,
        countId: baselineCount.id,
        itemCount: activeItems.length,
        linesCreated
      });
    } catch (error: any) {
      console.error("Initialize baseline error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get previous inventory count session (for comparison)
  // @ts-ignore
  app.get("/api/inventory-counts/:id/previous-lines", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId as string | undefined;
      if (!companyId) {
        return res.status(401).json({ error: "Unauthorized" });
      }
      const currentCountId = req.params.id;
      // @ts-ignore
      const currentCount = await storage.getInventoryCount(currentCountId);
      
      if (!currentCount) {
        return res.status(404).json({ error: "Count not found" });
      }
      
      if (currentCount.companyId !== companyId) {
        return res.status(404).json({ error: "Count not found" });
      }

      // Get counts from the same company and store, and find the one immediately before this one.
      // Primary sort: countDate (official inventory date); tiebreaker: countedAt (session creation time).
      // This handles same-day sessions where countDate is identical (both stored as local midnight).
      const allCounts = await storage.getInventoryCounts(currentCount.companyId, currentCount.storeId);
      const currentDate = new Date(currentCount.countDate).getTime();
      const currentCreated = new Date(currentCount.countedAt).getTime();
      const previousCount = allCounts
        .filter(c => {
          if (c.id === currentCount.id) return false;
          const cDate = new Date(c.countDate).getTime();
          if (cDate < currentDate) return true;
          // Same calendar date — use session creation time as tiebreaker
          if (cDate === currentDate) {
            return new Date(c.countedAt).getTime() < currentCreated;
          }
          return false;
        })
        .sort((a, b) => {
          const dateDiff = new Date(b.countDate).getTime() - new Date(a.countDate).getTime();
          if (dateDiff !== 0) return dateDiff;
          return new Date(b.countedAt).getTime() - new Date(a.countedAt).getTime();
        })[0];

      if (!previousCount) {
        return res.json({ previousCountId: null, lines: [] }); // No previous count exists
      }

      // Get the previous count's lines
      const previousLines = await storage.getInventoryCountLines(previousCount.id);
      
      res.json({ previousCountId: previousCount.id, lines: previousLines });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // Get item usage between latest two inventory counts for a store
  // @ts-ignore
  app.get("/api/stores/:storeId/usage", requireAuth, async (req, res) => {
    try {
      const storeId = req.params.storeId;
      const companyId = (req as any).companyId;
      
      // Get store to verify it exists and belongs to the company
      // @ts-ignore
      const store = await storage.getCompanyStore(storeId, companyId);
      if (!store) {
        return res.status(403).json({ error: "Access denied" });
      }

      // Get all counts for this store, sorted by count date descending
      // @ts-ignore
      const allCounts = await storage.getInventoryCounts(companyId, storeId);
      const sortedCounts = allCounts.sort((a, b) => 
        new Date(b.countDate).getTime() - new Date(a.countDate).getTime()
      );

      if (sortedCounts.length < 2) {
        // Need at least two counts to calculate usage
        return res.json([]);
      }

      const currentCount = sortedCounts[0];
      const previousCount = sortedCounts[1];

      // Calculate usage between the two counts
      const usageData = await storage.getItemUsageBetweenCounts(
        // @ts-ignore
        storeId,
        previousCount.id,
        currentCount.id
      );

      res.json(usageData);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // ============ UNIFIED ORDERS (Purchase + Transfer) ============
  app.get("/api/orders/unified", requireAuth, async (req, res) => {
    try {
      // @ts-ignore
      const companyId = req.companyId!;
      const storeId = req.query.storeId as string | undefined;
      const status = req.query.status as string | undefined;
      
      // Fetch both purchase orders and transfer orders
      const [purchaseOrders, transferOrders, vendors, stores, allReceipts] = await Promise.all([
        storage.getPurchaseOrders(companyId, storeId),
        storage.getTransferOrders(companyId, storeId),
        storage.getVendors(companyId),
        storage.getCompanyStores(companyId),
        storage.getReceipts(companyId)
      ]);
      
      // Build a map of purchase order ID to latest receipt completion timestamp
      const poCompletionMap = new Map<string, string>();
      for (const receipt of allReceipts) {
        if (receipt.status === "completed" && receipt.purchaseOrderId && receipt.receivedAt) {
          const existing = poCompletionMap.get(receipt.purchaseOrderId);
          if (!existing || new Date(receipt.receivedAt) > new Date(existing)) {
            // @ts-ignore
            poCompletionMap.set(receipt.purchaseOrderId, receipt.receivedAt);
          }
        }
      }
      
      // Transform purchase orders
      const poPromises = purchaseOrders.map(async (po) => {
        const vendor = vendors.find(v => v.id === po.vendorId);
        const store = stores.find(s => s.id === po.storeId);
        const lines = await storage.getPOLines(po.id);
        const lineCount = lines.length;
        const totalAmount = lines.reduce((sum, line) => sum + (line.orderedQty * line.priceEach), 0);
        
        // For received purchase orders, get completion timestamp from map
        const completedAt = po.status === "received" ? (poCompletionMap.get(po.id) || null) : null;
        
        return {
          id: po.id,
          type: "purchase" as const,
          status: po.status,
          createdAt: po.createdAt,
          expectedDate: po.expectedDate,
          completedAt: completedAt,
          vendorName: vendor?.name || "Unknown",
          fromStore: vendor?.name, // Vendor as "source" for purchase orders
          toStore: store?.name, // Receiving store
          storeId: po.storeId, // Store ID for filtering
          lineCount,
          totalAmount,
        };
      });
      
      // Collect all user IDs from transfer orders for batch lookup
      const transferUserIds: string[] = [];
      for (const to of transferOrders) {
        if (to.createdBy) transferUserIds.push(to.createdBy);
        if (to.executedBy) transferUserIds.push(to.executedBy);
        if (to.receivedBy) transferUserIds.push(to.receivedBy);
      }
      
      // Batch fetch user names (company-scoped for tenant isolation)
      const userMap = await storage.getUsersByIds(transferUserIds, companyId);
      
      // Transform transfer orders
      const toPromises = transferOrders.map(async (to) => {
        const fromStore = stores.find(s => s.id === to.fromStoreId);
        const toStore = stores.find(s => s.id === to.toStoreId);
        const lines = await storage.getTransferOrderLines(to.id);
        const lineCount = lines.length;
        
        // Calculate approximate total (items may not have prices, so this is best effort)
        const inventoryItems = await storage.getInventoryItems(undefined, undefined, companyId);
        let totalAmount = 0;
        for (const line of lines) {
          const item = inventoryItems.find(i => i.id === line.inventoryItemId);
          if (item && item.pricePerUnit) {
            totalAmount += line.requestedQty * item.pricePerUnit;
          }
        }
        
        return {
          id: to.id,
          type: "transfer" as const,
          status: to.status,
          createdAt: to.createdAt,
          expectedDate: to.expectedDate,
          completedAt: to.completedAt || null,
          vendorName: `${fromStore?.name || "Unknown"} → ${toStore?.name || "Unknown"}`,
          fromStore: fromStore?.name,
          toStore: toStore?.name,
          fromStoreId: to.fromStoreId, // Store IDs for filtering
          toStoreId: to.toStoreId,
          lineCount,
          totalAmount,
          // User accountability fields
          createdBy: to.createdBy,
          createdByName: to.createdBy ? userMap.get(to.createdBy)?.fullName || null : null,
          executedBy: to.executedBy,
          executedByName: to.executedBy ? userMap.get(to.executedBy)?.fullName || null : null,
          receivedBy: to.receivedBy,
          receivedByName: to.receivedBy ? userMap.get(to.receivedBy)?.fullName || null : null,
        };
      });
      
      // Wait for all enrichment
      const enrichedPOs = await Promise.all(poPromises);
      const enrichedTOs = await Promise.all(toPromises);
      
      // Combine and filter by status if provided
      let unified = [...enrichedPOs, ...enrichedTOs];
      if (status) {
        unified = unified.filter(order => order.status === status);
      }
      
      // Sort by created date descending (newest first)
      unified.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
      
      res.json(unified);
    } catch (error: any) {
      console.error("Unified orders error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // ============ PURCHASE ORDERS ============
  app.get("/api/purchase-orders", requireAuth, async (req, res) => {
    const companyId = (req as any).companyId;
    const storeId = req.query.storeId as string | undefined;
    
    const orders = await storage.getPurchaseOrders(companyId, storeId);
    const vendors = await storage.getVendors(companyId);
    
    const enriched = await Promise.all(orders.map(async (po) => {
      const vendor = vendors.find((v) => v.id === po.vendorId);
      const lines = await storage.getPOLines(po.id);
      const lineCount = lines.length;
      const totalAmount = lines.reduce((sum, line) => sum + (line.orderedQty * line.priceEach), 0);
      
      // For received orders, calculate actual received amount from receipts
      let receivedAmount = 0;
      if (po.status === "received") {
        const allReceipts = await storage.getReceipts(companyId);
        const poReceipts = allReceipts.filter(r => r.purchaseOrderId === po.id && r.status === "completed");
        
        for (const receipt of poReceipts) {
          const receiptLines = await storage.getReceiptLinesByReceiptId(receipt.id);
          receivedAmount += receiptLines.reduce((sum, line) => sum + (line.receivedQty * line.priceEach), 0);
        }
      }
      
      return {
        ...po,
        vendorName: vendor?.name || "Unknown",
        lineCount,
        totalAmount,
        receivedAmount,
      };
    }));
    
    // Sort by created date descending (newest first)
    enriched.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    
    res.json(enriched);
  });

  // Get pending order deadlines based on vendor delivery schedules
  // @ts-ignore
  app.get("/api/purchase-orders/deadlines", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const storeId = req.query.storeId as string | undefined;

      // Get pending purchase orders for the store
      const allOrders = await storage.getPurchaseOrders(companyId, storeId);
      const pendingOrders = allOrders.filter(po => po.status === "pending");
      
      if (pendingOrders.length === 0) {
        return res.json([]);
      }

      // Get vendors to access delivery schedules
      const vendors = await storage.getVendors(companyId);
      
      // Helper function to calculate next delivery date
      const getNextDeliveryDate = (deliveryDays: string[] | null, fromDate: Date = new Date()): Date | null => {
        if (!deliveryDays || deliveryDays.length === 0) {
          return null;
        }
        
        const dayNames = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
        const deliveryDayIndices = deliveryDays.map(day => dayNames.indexOf(day.toLowerCase()));
        
        // Start from today (normalized to midnight)
        const searchDate = new Date(fromDate);
        searchDate.setHours(0, 0, 0, 0);
        
        // Search up to 14 days ahead for next delivery day (including today)
        for (let i = 0; i < 14; i++) {
          const dayOfWeek = searchDate.getDay();
          if (deliveryDayIndices.includes(dayOfWeek)) {
            return new Date(searchDate);
          }
          searchDate.setDate(searchDate.getDate() + 1);
        }
        
        return null;
      };

      // Calculate deadlines for each pending order
      const deadlines = pendingOrders.map(po => {
        const vendor = vendors.find(v => v.id === po.vendorId);
        if (!vendor) {
          return null;
        }

        const nextDelivery = getNextDeliveryDate(vendor.deliveryDays);
        if (!nextDelivery) {
          return null;
        }

        // Calculate order deadline (delivery date - lead days)
        const leadDays = vendor.leadDaysAhead || 0;
        const deadline = new Date(nextDelivery);
        deadline.setDate(deadline.getDate() - leadDays);
        
        // Calculate days until deadline
        const now = new Date();
        now.setHours(0, 0, 0, 0);
        const daysUntilDeadline = Math.ceil((deadline.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
        
        return {
          purchaseOrderId: po.id,
          // @ts-ignore
          internalOrderId: po.internalOrderId,
          vendorId: vendor.id,
          vendorName: vendor.name,
          nextDeliveryDate: nextDelivery.toISOString().split('T')[0], // YYYY-MM-DD
          orderDeadline: deadline.toISOString().split('T')[0], // YYYY-MM-DD
          daysUntilDeadline,
          leadDaysAhead: leadDays,
          isUrgent: daysUntilDeadline <= 1, // Deadline today or tomorrow
          isPastDue: daysUntilDeadline < 0, // Deadline has passed
        };
      }).filter(d => d !== null);

      // Sort by urgency (past due first, then by days until deadline ascending)
      deadlines.sort((a, b) => {
        if (a.isPastDue && !b.isPastDue) return -1;
        if (!a.isPastDue && b.isPastDue) return 1;
        return a.daysUntilDeadline - b.daysUntilDeadline;
      });

      res.json(deadlines);
    } catch (error: any) {
      console.error("Deadline calculation error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // @ts-ignore
  app.get("/api/purchase-orders/:id", requireAuth, async (req, res) => {
    const companyId = (req as any).companyId;
    // @ts-ignore
    const po = await storage.getPurchaseOrder(req.params.id, companyId);
    if (!po) {
      return res.status(404).json({ error: "Purchase order not found" });
    }

    // @ts-ignore
    const lines = await storage.getPOLines(req.params.id);
    const vendorItems = await storage.getVendorItems(undefined, companyId);
    const inventoryItems = await storage.getInventoryItems(undefined, undefined, companyId);
    const units = await storage.getUnits();

    const enrichedLines = lines.map((line) => {
      const vi = vendorItems.find((vi) => vi.id === line.vendorItemId);
      const item = inventoryItems.find((i) => i.id === vi?.inventoryItemId);
      const unit = units.find((u) => u.id === line.unitId);
      
      // Use the original PO price (priceEach) - this is the price per unit when ordered
      const pricePerUnit = line.priceEach;
      // Use vendor item's caseSize (not inventory item's) for accurate order display
      const caseSize = vi?.caseSize || 1;
      
      return {
        ...line,
        inventoryItemId: vi?.inventoryItemId,
        itemName: item?.name || "Unknown",
        vendorSku: vi?.vendorSku || "",
        unitName: unit?.name || "",
        caseQuantity: line.caseQuantity,
        pricePerUnit: pricePerUnit, // Use PO line price (price per unit when ordered)
        caseSize: caseSize, // Need this to calculate totals
      };
    });

    res.json({
      ...po,
      lines: enrichedLines,
    });
  });

