  app.post("/api/purchase-orders", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const { lines, ...poData } = req.body;
      
      // Add companyId from authenticated context
      const poInput = insertPurchaseOrderSchema.parse({
        ...poData,
        companyId,
      });
      const po = await storage.createPurchaseOrder(poInput);

      if (lines && Array.isArray(lines)) {
        for (const line of lines) {
          let vendorItemId = line.vendorItemId;
          
          // Check if this is a misc grocery order with inventoryItemId instead
          if (line.inventoryItemId) {
            // Check if vendor item already exists for this vendor and inventory item
            const vendorItems = await storage.getVendorItems(po.vendorId);
            const existingVendorItem = vendorItems.find(
              vi => vi.inventoryItemId === line.inventoryItemId
            );
            
            if (existingVendorItem) {
              vendorItemId = existingVendorItem.id;
            } else {
              // Create a vendor item on the fly for this inventory item.
              // M3A: po_create is a quote source — price fields stamped via shared
              // service AFTER create (no direct lastPrice write on createVendorItem).
              const newVendorItem = await storage.createVendorItem({
                vendorId: po.vendorId,
                inventoryItemId: line.inventoryItemId,
                purchaseUnitId: line.unitId,
                caseSize: 1,
                active: 1,
              });
              vendorItemId = newVendorItem.id;
              if (line.priceEach > 0) {
                await recordVendorPrice({
                  vendorItemId: newVendorItem.id,
                  inventoryItemId: line.inventoryItemId,
                  priceBasis: "unit",
                  price: line.priceEach,
                  caseSize: 1,
                  source: "po_create",
                  representsActualPurchase: false,
                });
              }
            }
          }
          
          const lineData = insertPOLineSchema.parse({
            vendorItemId,
            orderedQty: line.orderedQty,
            caseQuantity: line.caseQuantity,
            unitId: line.unitId,
            priceEach: line.priceEach,
            purchaseOrderId: po.id,
          });
          await storage.createPOLine(lineData);
        }
      }

      res.status(201).json(po);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // @ts-ignore
  app.patch("/api/purchase-orders/:id", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      // @ts-ignore
      const po = await storage.getPurchaseOrder(req.params.id, companyId);
      if (!po) {
        return res.status(404).json({ error: "Purchase order not found" });
      }

      const { lines, ...poData } = req.body;
      
      // Validate and update the purchase order
      const validatedData = insertPurchaseOrderSchema.partial().parse(poData);
      
      // @ts-ignore
      await storage.updatePurchaseOrder(req.params.id, validatedData);

      // Update lines if provided
      if (lines && Array.isArray(lines)) {
        // Delete existing lines
        // @ts-ignore
        const existingLines = await storage.getPOLines(req.params.id);
        for (const line of existingLines) {
          await storage.deletePOLine(line.id);
        }

        // Create new lines
        for (const line of lines) {
          let vendorItemId = line.vendorItemId;
          
          // Check if this is a misc grocery order with inventoryItemId instead
          if (line.inventoryItemId) {
            // Check if vendor item already exists for this vendor and inventory item
            const vendorItems = await storage.getVendorItems(po.vendorId, companyId);
            const existingVendorItem = vendorItems.find(
              vi => vi.inventoryItemId === line.inventoryItemId
            );
            
            if (existingVendorItem) {
              vendorItemId = existingVendorItem.id;
            } else {
              // Create a vendor item on the fly for this inventory item.
              // M3A: po_create is a quote source — price fields stamped via shared
              // service AFTER create (no direct lastPrice write on createVendorItem).
              const newVendorItem = await storage.createVendorItem({
                vendorId: po.vendorId,
                inventoryItemId: line.inventoryItemId,
                purchaseUnitId: line.unitId,
                caseSize: 1,
                active: 1,
              });
              vendorItemId = newVendorItem.id;
              if (line.priceEach > 0) {
                await recordVendorPrice({
                  vendorItemId: newVendorItem.id,
                  inventoryItemId: line.inventoryItemId,
                  priceBasis: "unit",
                  price: line.priceEach,
                  caseSize: 1,
                  source: "po_create",
                  representsActualPurchase: false,
                });
              }
            }
          }
          
          const lineData = insertPOLineSchema.parse({
            vendorItemId,
            orderedQty: line.orderedQty,
            caseQuantity: line.caseQuantity,
            unitId: line.unitId,
            priceEach: line.priceEach,
            purchaseOrderId: req.params.id,
          });
          await storage.createPOLine(lineData);
        }
      }

      // @ts-ignore
      const updatedPO = await storage.getPurchaseOrder(req.params.id, companyId);
      res.json(updatedPO);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // ── PO Export ────────────────────────────────────────────────────────────────

  // Validate or generate a supplier-formatted order CSV
  // ?validateOnly=true returns validation result without rendering the file
  app.post("/api/purchase-orders/:id/export", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId;
      const userId = (req as any).userId;
      const { connectorId: requestedConnector } = req.body || {};

      // @ts-ignore
      const po = await storage.getPurchaseOrder(req.params.id, companyId);
      if (!po) return res.status(404).json({ error: "Purchase order not found" });

      // @ts-ignore
      const [vendor] = await db.select().from(vendors).where(eq(vendors.id, po.vendorId));
      if (!vendor) return res.status(404).json({ error: "Vendor not found" });

      // @ts-ignore
      const lines = await storage.getPOLines(req.params.id);
      const allVendorItems = await storage.getVendorItems(po.vendorId);
      const allInventoryItems = await storage.getInventoryItems(undefined, undefined, companyId);
      const units = await storage.getUnits();

      const enrichedLines = lines.map((line) => {
        const vi = allVendorItems.find((vi) => vi.id === line.vendorItemId);
        const item = allInventoryItems.find((i) => i.id === vi?.inventoryItemId);
        const unit = units.find((u) => u.id === line.unitId);
        return {
          itemName: item?.name || "Unknown",
          vendorSku: vi?.vendorSku || null,
          orderedQty: line.orderedQty,
          caseQuantity: line.caseQuantity,
          unitName: unit?.name || "",
          priceEach: line.priceEach,
          caseSize: vi?.caseSize || 1,
        };
      });

      const connectorId = requestedConnector || await resolveConnectorId(companyId, po.vendorId);
      const renderer = getExportRenderer(connectorId);

      const exportInput = {
        purchaseOrderId: po.id,
        vendorName: vendor.name,
        accountNumber: vendor.accountNumber || null,
        expectedDate: po.expectedDate ? new Date(po.expectedDate).toISOString().slice(0, 10) : null,
        notes: (po as any).notes || null,
        exportedAt: new Date(),
        lines: enrichedLines,
      };

      const validation = renderer.validate(exportInput);

      // Validate-only: return result without rendering
      if (req.query.validateOnly === "true") {
        return res.json({
          data: {
            validation,
            connectorId,
            displayName: renderer.displayName,
          },
        });
      }

      if (!validation.canExport) {
        return res.status(422).json({ error: "Export blocked by validation errors", errors: validation.errors });
      }

      const result = renderer.render(exportInput);

      await storage.createPoExportLog({
        purchaseOrderId: po.id,
        companyId,
        vendorId: po.vendorId,
        connectorId,
        exportedBy: userId,
        fileFormat: renderer.format,
        lineCount: result.lineCount,
        warnings: result.warnings.length > 0 ? (result.warnings as any) : null,
      });

      res.setHeader("Content-Type", result.mimeType);
      res.setHeader("Content-Disposition", `attachment; filename="${result.filename}"`);
      return res.send(result.buffer);
    } catch (err: any) {
      console.error("[PO Export]", err);
      return res.status(500).json({ error: err.message || "Export failed" });
    }
  });

