  /**
   * POST /api/menu-items/seed-recipes
   * On-demand seeding: for every menu item in the company that has a
   * non-empty `description` and no linked recipe, parse the description
   * into ingredient tokens and create a recipe stub + placeholder components.
   */
  // @ts-ignore
  app.post("/api/menu-items/seed-recipes", requireAuth, async (req, res) => {
    try {
      // @ts-ignore
      const companyId = req.companyId!;
      // Fetch all menu items for the company that have a description but no recipeId
      const candidateItems = await db
        .select({ id: menuItems.id, name: menuItems.name, description: menuItems.description, price: menuItems.price })
        .from(menuItems)
        .where(
          and(
            // @ts-ignore
            eq(menuItems.companyId, companyId),
            // @ts-ignore
            isNotNull(menuItems.description),
            // @ts-ignore
            isNull(menuItems.recipeId)
          )
        );

      const withDescriptions = candidateItems.filter(
        // @ts-ignore
        (item) => item.description && item.description.trim().length > 0
      ) as Array<{ id: string; name: string; description: string; price: number | null }>;

      if (withDescriptions.length === 0) {
        return res.json({ recipesCreated: 0, message: "No eligible menu items found — all items either already have a recipe or have no description." });
      }

      const { seedRecipesFromDescriptions } = await import('./services/menuRecipeSeeder');
      const seeded = await seedRecipesFromDescriptions(withDescriptions, companyId);

      return res.json({ recipesCreated: seeded.length });
    } catch (error: any) {
      console.error("[Seed Recipes from Menu Error]", error);
      res.status(500).json({ error: error.message });
    }
  });

  // ============ MENU ITEM HIERARCHY ============
  
  // Get menu items with their size variants (hierarchical view)
  app.get("/api/menu-items/hierarchy", requireAuth, async (req, res) => {
    try {
      // @ts-ignore
      const companyId = req.companyId!;
      const hierarchy = await storage.getMenuItemsWithVariants(companyId);
      
      // Also fetch store assignments for each item
      const allStoreAssignments = await db.select().from(storeMenuItems)
        // @ts-ignore
        .where(eq(storeMenuItems.companyId, companyId));
      
      const storeAssignmentMap = new Map<string, string[]>();
      for (const assignment of allStoreAssignments) {
        const existing = storeAssignmentMap.get(assignment.menuItemId) || [];
        existing.push(assignment.storeId);
        storeAssignmentMap.set(assignment.menuItemId, existing);
      }
      
      // Fetch recipes for cost info
      const allRecipes = await db.select({
        id: recipes.id,
        name: recipes.name,
        computedCost: recipes.computedCost,
        isPlaceholder: recipes.isPlaceholder,
      // @ts-ignore
      }).from(recipes).where(eq(recipes.companyId, companyId));
      
      // @ts-ignore
      const recipeMap = new Map(allRecipes.map(r => [r.id, r]));
      
      // Enrich with store assignments and recipe info
      const enrichedHierarchy = hierarchy.map(group => ({
        parent: {
          ...group.parent,
          storeIds: storeAssignmentMap.get(group.parent.id) || [],
          recipe: group.parent.recipeId ? recipeMap.get(group.parent.recipeId) : null,
        },
        variants: group.variants.map(v => ({
          ...v,
          storeIds: storeAssignmentMap.get(v.id) || [],
          recipe: v.recipeId ? recipeMap.get(v.recipeId) : null,
        })),
      }));
      
      res.json(enrichedHierarchy);
    } catch (error: any) {
      console.error("[Menu Items Hierarchy Error]", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get variants for a specific menu item
