  // GET /api/menu-items/:id/prep-styles — list prep-style recipe links with cost and margin
  app.get("/api/menu-items/:id/prep-styles", requireAuth, async (req, res) => {
    try {
      const { id } = req.params;
      // @ts-ignore
      const companyId = req.companyId!;

      const [menuItem] = await db.select({ id: menuItems.id, price: menuItems.price })
        .from(menuItems)
        // @ts-ignore
        .where(and(eq(menuItems.id, id), eq(menuItems.companyId, companyId)))
        .limit(1);
      if (!menuItem) return res.status(404).json({ error: "Menu item not found" });

      const rows = await db.select({
        id: menuItemRecipes.id,
        menuItemId: menuItemRecipes.menuItemId,
        recipeId: menuItemRecipes.recipeId,
        prepStyleLabel: menuItemRecipes.prepStyleLabel,
        sortOrder: menuItemRecipes.sortOrder,
        recipeComputedCost: recipes.computedCost,
        recipeName: recipes.name,
        recipeIsPlaceholder: recipes.isPlaceholder,
      })
        .from(menuItemRecipes)
        // @ts-ignore
        .innerJoin(recipes, eq(menuItemRecipes.recipeId, recipes.id))
        // @ts-ignore
        .where(eq(menuItemRecipes.menuItemId, id))
        // @ts-ignore
        .orderBy(asc(menuItemRecipes.sortOrder));

      // Compute margin % per row using the menu item's selling price
      // marginPct = (sellingPrice - recipeCost) / sellingPrice * 100
      const sellingPrice = menuItem.price;
      // @ts-ignore
      const enriched = rows.map((row) => {
        let marginPct: number | null = null;
        if (
          sellingPrice != null &&
          sellingPrice > 0 &&
          row.recipeComputedCost != null &&
          row.recipeComputedCost >= 0
        ) {
          marginPct = Math.round(((sellingPrice - row.recipeComputedCost) / sellingPrice) * 10000) / 100;
        }
        return { ...row, sellingPrice, marginPct };
      });

      return res.json(enriched);
    } catch (err) {
      console.error("GET /api/menu-items/:id/prep-styles error:", err);
      return res.status(500).json({ error: "Failed to fetch prep styles" });
    }
  });

  // POST /api/menu-items/link-as-variants — link a detected variant group as parent/child items
  // Body: { itemIds: string[] } — first ID becomes the parent, rest become children
  app.post("/api/menu-items/link-as-variants", requireAuth, async (req, res) => {
    try {
      // @ts-ignore
      const companyId = req.companyId!;
      const { itemIds } = req.body;

      if (!Array.isArray(itemIds) || itemIds.length < 2) {
        return res.status(400).json({ error: "At least 2 item IDs are required" });
      }

      // Verify all items belong to this company and have no existing parent
      const itemRows = await db.select({ id: menuItems.id, parentMenuItemId: menuItems.parentMenuItemId, name: menuItems.name })
        .from(menuItems)
        // @ts-ignore
        .where(and(inArray(menuItems.id, itemIds), eq(menuItems.companyId, companyId)));

      if (itemRows.length !== itemIds.length) {
        return res.status(400).json({ error: "One or more items not found" });
      }

      // Reject items already linked to a different parent
      const alreadyLinked = itemRows.filter(
        // @ts-ignore
        (r) => r.parentMenuItemId != null && !itemIds.includes(r.parentMenuItemId)
      );
      if (alreadyLinked.length > 0) {
        // @ts-ignore
        const names = alreadyLinked.map((r) => r.name).join(", ");
        return res.status(409).json({
          error: `One or more items already belong to a variant group: ${names}`,
        });
      }

      const [parentItem, ...childItems] = itemIds;

      // Set children's parentMenuItemId to parentItem
      await db.update(menuItems)
        .set({ parentMenuItemId: parentItem })
        // @ts-ignore
        .where(and(inArray(menuItems.id, childItems), eq(menuItems.companyId, companyId)));

      return res.json({ success: true, parentId: parentItem, childIds: childItems });
    } catch (err) {
      console.error("POST /api/menu-items/link-as-variants error:", err);
      return res.status(500).json({ error: "Failed to link variants" });
    }
  });

  // POST /api/menu-items/:id/prep-styles — add a prep-style recipe link
  app.post("/api/menu-items/:id/prep-styles", requireAuth, async (req, res) => {
    try {
      const { id } = req.params;
      // @ts-ignore
      const companyId = req.companyId!;
      const { recipeId, prepStyleLabel } = req.body;

      if (!recipeId || !prepStyleLabel?.trim()) {
        return res.status(400).json({ error: "recipeId and prepStyleLabel are required" });
      }

      const [menuItem] = await db.select({ id: menuItems.id })
        .from(menuItems)
        // @ts-ignore
        .where(and(eq(menuItems.id, id), eq(menuItems.companyId, companyId)))
        .limit(1);
      if (!menuItem) return res.status(404).json({ error: "Menu item not found" });

      const [recipe] = await db.select({ id: recipes.id })
        .from(recipes)
        // @ts-ignore
        .where(and(eq(recipes.id, recipeId), eq(recipes.companyId, companyId)))
        .limit(1);
      if (!recipe) return res.status(404).json({ error: "Recipe not found" });

      const maxSortOrder = await db.select({ maxSort: sql<number>`COALESCE(MAX(sort_order), -1)` })
        .from(menuItemRecipes)
        // @ts-ignore
        .where(eq(menuItemRecipes.menuItemId, id));
      const nextSort = (maxSortOrder[0]?.maxSort ?? -1) + 1;

      const [created] = await db.insert(menuItemRecipes).values({
        companyId,
        menuItemId: id,
        recipeId,
        prepStyleLabel: prepStyleLabel.trim(),
        sortOrder: nextSort,
      }).returning();

      return res.status(201).json(created);
    } catch (err: any) {
      if (err.code === "23505") {
        return res.status(409).json({ error: "This recipe is already linked as a prep style for this item" });
      }
      console.error("POST /api/menu-items/:id/prep-styles error:", err);
      return res.status(500).json({ error: "Failed to add prep style" });
    }
  });

