  // @ts-ignore
  app.post("/api/transfers", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      const data = insertTransferLogSchema.parse(req.body);
      
      // Get inventory items at from location
      // @ts-ignore
      const inventoryItems = await storage.getInventoryItems(data.fromLocationId);
      const fromItem = inventoryItems.find(i => i.id === data.inventoryItemId);
      // @ts-ignore
      const fromQty = fromItem?.onHandQty || 0;
      
      // Validate sufficient quantity
      if (fromQty < data.qty) {
        return res.status(400).json({ 
          error: `Insufficient inventory. Available: ${fromQty}, Requested: ${data.qty}` 
        });
      }
      
      // Create transfer log
      const transfer = await storage.createTransferLog(data);
      
      // Update from location inventory
      if (fromItem) {
        await storage.updateInventoryItem(fromItem.id, {
          // @ts-ignore
          onHandQty: fromQty - data.qty
        });
      }
      
      // Update to location inventory
      // @ts-ignore
      const toItems = await storage.getInventoryItems(data.toLocationId);
      const toItem = toItems.find(i => i.id === data.inventoryItemId);
      if (toItem) {
        await storage.updateInventoryItem(toItem.id, {
          // @ts-ignore
          onHandQty: (toItem.onHandQty || 0) + data.qty
        });
      }
      
      res.status(201).json(transfer);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // ============ WASTE LOGS ============
  // @ts-ignore
  app.get("/api/waste", requireAuth, async (req, res) => {
    const storeId = req.query.storeId as string | undefined;
    const wasteType = req.query.wasteType as string | undefined;
    const startDate = req.query.startDate as string | undefined;
    const endDate = req.query.endDate as string | undefined;
    
    // Get accessible stores for the user
    // @ts-ignore
    const accessibleStoreIds = await getAccessibleStores(req.user!, req.companyId);
    
    // @ts-ignore
    const wasteLogs = await storage.getWasteLogs(req.companyId!);
    
    // Filter to only show waste from stores the user has access to
    let filtered = wasteLogs.filter(log => accessibleStoreIds.includes(log.storeId));
    
    // Further filter by specific storeId if provided
    if (storeId) {
      // Verify user has access to the requested store
      if (!accessibleStoreIds.includes(storeId)) {
        return res.status(403).json({ error: "Access denied to this store" });
      }
      filtered = filtered.filter(log => log.storeId === storeId);
    }
    
    if (wasteType) {
      filtered = filtered.filter(log => log.wasteType === wasteType);
    }
    
    // Filter by date range
    if (startDate) {
      const start = new Date(startDate);
      start.setHours(0, 0, 0, 0);
      filtered = filtered.filter(log => new Date(log.wastedAt) >= start);
    }
    
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59, 999);
      filtered = filtered.filter(log => new Date(log.wastedAt) <= end);
    }
    
    // Collect user IDs for batch lookup
    const userIds: string[] = [];
    for (const log of filtered) {
      if (log.loggedBy) userIds.push(log.loggedBy);
    }
    // @ts-ignore
    const userMap = await storage.getUsersByIds(userIds, req.companyId!);
    
    // Build a menu-item recipeId lookup for noRecipeLinked annotation
    const menuItemWasteIds = Array.from(
      new Set(filtered.filter(l => l.wasteType === "menu_item" && l.menuItemId).map(l => l.menuItemId!))
    );
    let menuItemRecipeMap = new Map<string, string | null>();
    if (menuItemWasteIds.length > 0) {
      // @ts-ignore
      const allMenuItems = await storage.getMenuItems(req.companyId!);
      for (const mi of allMenuItems) {
        if (menuItemWasteIds.includes(mi.id)) {
          menuItemRecipeMap.set(mi.id, mi.recipeId ?? null);
        }
      }
    }

    // Enrich with user names and noRecipeLinked flag
    const enriched = filtered.map(log => {
      const noRecipeLinked =
        log.wasteType === "menu_item" &&
        log.menuItemId != null &&
        log.totalValue === 0 &&
        menuItemRecipeMap.get(log.menuItemId!) === null;
      return {
        ...log,
        loggedByName: log.loggedBy ? userMap.get(log.loggedBy)?.fullName || null : null,
        noRecipeLinked: noRecipeLinked || false,
      };
    });
    
    res.json(enriched);
  });

  // @ts-ignore
  app.post("/api/waste", requireAuth, async (req, res) => {
    try {
      const data = createWasteLogSchema.parse(req.body);
      
      // Verify user has access to the selected store
      // @ts-ignore
      const accessibleStoreIds = await getAccessibleStores(req.user!, req.companyId);
      if (!accessibleStoreIds.includes(data.storeId)) {
        return res.status(403).json({ error: "Access denied to this store" });
      }
      
      if (data.wasteType === 'inventory') {
        // Inventory waste: direct inventory reduction
        if (!data.inventoryItemId) {
          return res.status(400).json({ error: "Inventory item ID is required for inventory waste" });
        }
        
        // Get inventory items for the company (pass companyId as 3rd parameter)
        // @ts-ignore
        const inventoryItems = await storage.getInventoryItems(undefined, undefined, req.companyId!);
        const item = inventoryItems.find(i => i.id === data.inventoryItemId);
        
        if (!item) {
          return res.status(404).json({ error: "Inventory item not found" });
        }
        
        // Calculate value using company costing method (Last Cost vs WAC)
        // @ts-ignore
        const wasteCompany = await storage.getCompany(req.companyId!);
        const totalValue = data.qty * getEffectiveUnitCost(item, wasteCompany);
        
        // Create waste log with calculated value
        const wasteLog = await storage.createWasteLog({
          ...data,
          // @ts-ignore
          companyId: req.companyId!,
          totalValue,
          // @ts-ignore
          loggedBy: req.user!.id,
        });
        
        res.status(201).json(wasteLog);
        
      } else if (data.wasteType === 'menu_item') {
        // Menu item waste: calculate from recipe
        if (!data.menuItemId) {
          return res.status(400).json({ error: "Menu item ID is required for menu item waste" });
        }
        
        // @ts-ignore
        const menuItems = await storage.getMenuItems(req.companyId!);
        const menuItem = menuItems.find(m => m.id === data.menuItemId);
        
        if (!menuItem) {
          return res.status(404).json({ error: "Menu item not found" });
        }
        
        // Menu items without a linked recipe are still valid — log waste with $0 value
        let totalValue = 0;
        if (menuItem.recipeId) {
          // @ts-ignore
          const recipes = await storage.getRecipes(req.companyId!);
          const recipe = recipes.find(r => r.id === menuItem.recipeId);
          totalValue = (recipe?.computedCost || 0) * data.qty;
        }
        
        // Create waste log
        const wasteLog = await storage.createWasteLog({
          ...data,
          // @ts-ignore
          companyId: req.companyId!,
          totalValue,
          // @ts-ignore
          loggedBy: req.user!.id,
        });
        
        res.status(201).json({ ...wasteLog, noRecipeLinked: !menuItem.recipeId });
        
      } else {
        return res.status(400).json({ error: "Invalid waste type. Must be 'inventory' or 'menu_item'" });
      }
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // ── POST /api/waste/interpret ─────────────────────────────────────────────
  // Accepts either multipart/form-data (audio file) or application/json
  // (pre-transcribed text) and returns structured, store-resolved waste entries.
  const audioUploadMiddleware = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 10 * 1024 * 1024 }, // 10 MB hard limit
  }).single("audio");

  app.post("/api/waste/interpret", requireAuth, (req, res, next) => {
    // Only invoke multer for multipart requests; JSON goes straight through
    if (req.is("multipart/form-data")) {
      audioUploadMiddleware(req, res, next);
    } else {
      next();
    }
  }, async (req, res) => {
    try {
      let transcript: string;
      let transcriptionModel: string | null = null;
      let storeId: string;
      let requestId: string;

      // ── Determine input path ──────────────────────────────────────────────
      if ((req as any).file) {
        // Audio path — file already in memory via multer
        const file = (req as any).file as Express.Multer.File;
        storeId = String(req.body?.storeId ?? "");
        requestId = String(req.body?.requestId ?? crypto.randomUUID());

        const mimeExtMap: Record<string, string> = {
          "audio/webm": "webm",
          "audio/mp4": "mp4",
          "audio/mpeg": "mp3",
          "audio/ogg": "ogg",
          "audio/wav": "wav",
          "audio/x-m4a": "m4a",
        };
        const base = file.mimetype.split(";")[0].trim();
        const ext = mimeExtMap[base] ?? "webm";

        // Reject zero-byte uploads before hitting the transcription API
        const { validateAudioBuffer } = await import("./lib/audioValidation");
        const audioErr = validateAudioBuffer(file.buffer);
        if (audioErr) {
          return res.status(audioErr.status).json({ error: audioErr.error });
        }

        const result = await transcribeAudio(file.buffer, file.mimetype, ext, {
          // @ts-ignore
          companyId: req.companyId!,
          userId: (req as any).user?.id ?? null,
        });
        transcript = result.transcript;
        transcriptionModel = result.model;
      } else {
        // JSON transcript path
        const schema = z.object({
          storeId: z.string().uuid("storeId must be a valid UUID"),
          transcript: z.string().min(1).max(5100),
          requestId: z.string().optional(),
        });
        const parsed = schema.safeParse(req.body);
        if (!parsed.success) {
          return res.status(400).json({ error: "Invalid request", details: parsed.error.flatten() });
        }
        storeId = parsed.data.storeId;
        transcript = parsed.data.transcript;
        requestId = parsed.data.requestId ?? (crypto.randomUUID() as string);
      }

      // ── Auth / store access ───────────────────────────────────────────────
      if (!storeId || !/^[0-9a-f-]{36}$/i.test(storeId)) {
        return res.status(400).json({ error: "storeId must be a valid UUID" });
      }
      // @ts-ignore
      const accessibleStoreIds = await getAccessibleStores(req.user!, req.companyId);
      if (!accessibleStoreIds.includes(storeId)) {
        return res.status(403).json({ error: "Access denied to this store" });
      }

      // ── Enforce transcript limits ─────────────────────────────────────────
      const responseWarnings: string[] = [];
      if (transcript.length > 5000) {
        responseWarnings.push("Transcript was truncated to 5,000 characters");
        transcript = transcript.slice(0, 5000);
      }
      if (!transcript.trim()) {
        return res.status(400).json({ error: "No transcript to interpret" });
      }

      // ── Extract spoken entries ────────────────────────────────────────────
      const { entries: spokenEntries, model: interpretationModel } =
        await extractSpokenWasteEntries(transcript, {
          // @ts-ignore
          companyId: req.companyId!,
          userId: (req as any).user?.id ?? null,
        });

      // ── Fetch catalog data for resolution ─────────────────────────────────
      const [allInventoryItems, allMenuItems, allUnits, allItemUnits] = await Promise.all([
        // @ts-ignore
        storage.getInventoryItems(undefined, undefined, req.companyId!),
        // @ts-ignore
        storage.getMenuItemsByCompany(req.companyId!),
        storage.getUnits(),
        // @ts-ignore
        storage.getInventoryItemUnitsForCompany(req.companyId!),
      ]);

      // ── Resolve entries against the catalog ──────────────────────────────
      const resolvedEntries = resolveSpokenWasteEntries({
        inventoryItems: allInventoryItems as any[],
        menuItems: allMenuItems as any[],
        units: allUnits,
        itemUnits: allItemUnits.map((iu: any) => ({
          inventoryItemId: iu.inventoryItemId,
          unitId: iu.unitId,
        })),
        entries: spokenEntries,
      });

      // ── Write interpret logs (fire-and-forget, never fail the request) ──────
      if (resolvedEntries.length > 0) {
        // @ts-ignore
        const companyId = req.companyId!;
        const logRows = resolvedEntries.map(entry => ({
          companyId,
          storeId,
          spokenItem: entry.spokenItem,
          resolutionStatus: entry.resolutionStatus,
          matchedItemId: entry.itemId ?? null,
          matchScore: entry.matchScore,
        }));
        db.insert(voiceInterpretLogs).values(logRows).catch((logErr: unknown) => {
          console.error("[waste/interpret] log write error:", logErr);
        });
      }

      return res.json({
        requestId,
        transcript,
        transcriptionModel,
        interpretationModel,
        entries: resolvedEntries,
        warnings: responseWarnings,
      });
    } catch (err: any) {
      console.error("[waste/interpret] error:", err);
      if (err.status === 413 || err.message?.includes("10 MB") || err.message?.includes("File too large")) {
        return res.status(413).json({ error: "Audio file exceeds the 10 MB limit" });
      }
      return res.status(500).json({ error: err.message ?? "Failed to interpret waste entry" });
    }
  });

  app.get("/api/reports/waste-trends", requireAuth, async (req, res) => {
    const startDate = req.query.start ? new Date(req.query.start as string) : undefined;
    const endDate = req.query.end ? new Date(req.query.end as string) : undefined;
    
    // Get accessible stores for the user
    // @ts-ignore
    const accessibleStoreIds = await getAccessibleStores(req.user!, req.companyId);
    
    // @ts-ignore
    const wasteLogs = await storage.getWasteLogs(req.companyId!, undefined, undefined, startDate, endDate);
    
    // Filter to only show waste from stores the user has access to
    const filteredWasteLogs = wasteLogs.filter(log => accessibleStoreIds.includes(log.storeId));
    
    // Get inventory items for the company (pass companyId as 3rd parameter)
    // @ts-ignore
    const inventoryItems = await storage.getInventoryItems(undefined, undefined, req.companyId!);
    const trends: Record<string, any> = {};
    for (const wasteLog of filteredWasteLogs) {
      if (!trends[wasteLog.inventoryItemId]) {
        const item = inventoryItems.find(i => i.id === wasteLog.inventoryItemId);
        trends[wasteLog.inventoryItemId] = { productId: wasteLog.inventoryItemId, productName: item?.name || "Unknown", totalWasteQty: 0, totalWasteCost: 0, byReason: {} as Record<string, number>, count: 0 };
      }
      const item = inventoryItems.find(i => i.id === wasteLog.inventoryItemId);
      const pricePerUnit = item?.pricePerUnit || 0;
      trends[wasteLog.inventoryItemId].totalWasteQty += wasteLog.qty;
      trends[wasteLog.inventoryItemId].totalWasteCost += wasteLog.qty * pricePerUnit;
      trends[wasteLog.inventoryItemId].count += 1;
      if (!trends[wasteLog.inventoryItemId].byReason[wasteLog.reasonCode]) trends[wasteLog.inventoryItemId].byReason[wasteLog.reasonCode] = 0;
      trends[wasteLog.inventoryItemId].byReason[wasteLog.reasonCode] += wasteLog.qty;
    }
    res.json(Object.values(trends));
  });

  // GET /api/reports/voice-interpret-failures
  // Returns top unresolved/ambiguous spoken items over the last 30 days for the company.
  // Requires store_manager, company_admin, or global_admin role.
  // store_manager users see only aggregates from their accessible stores.
  app.get("/api/reports/voice-interpret-failures", requireAuth, async (req, res) => {
    try {
      const user = req.user!;
      const ALLOWED_ROLES = ["store_manager", "company_admin", "global_admin"] as const;
      // @ts-ignore
      if (!ALLOWED_ROLES.includes(user.role as any)) {
        return res.status(403).json({ error: "Manager or admin access required" });
      }

      // @ts-ignore
      const companyId = req.companyId!;
      const parsedDays = parseInt(String(req.query.days ?? "30"), 10);
      const days = Math.min(Math.max(isNaN(parsedDays) ? 30 : parsedDays, 1), 90);
      const cutoff = new Date(Date.now() - days * 24 * 60 * 60 * 1000);

      // Restrict to accessible stores (store_manager sees only their assigned stores)
      // @ts-ignore
      const accessibleStoreIds = await getAccessibleStores(user, companyId);

      if (accessibleStoreIds.length === 0) {
        return res.json({ days, rows: [] });
      }

      // Aggregate failure statuses only — unresolved, ambiguous, needs_unit.
      // "resolved" entries are excluded because the report exists to surface problems.
      const storeInClause = sql.join(
        accessibleStoreIds.map(id => sql`${id}`),
        sql`, `,
      );
      const rows = await db.execute(sql`
        SELECT
          spoken_item,
          resolution_status,
          COUNT(*)::int AS occurrences,
          ROUND(AVG(match_score)::numeric, 3)::real AS avg_score,
          MAX(created_at) AS last_seen_at,
          (ARRAY_AGG(matched_item_id ORDER BY created_at DESC))[1] AS matched_item_id
        FROM voice_interpret_logs
        WHERE company_id = ${companyId}
          AND store_id IN (${storeInClause})
          AND resolution_status IN ('unresolved', 'ambiguous', 'needs_unit')
          AND created_at >= ${cutoff.toISOString()}
        GROUP BY spoken_item, resolution_status
        ORDER BY occurrences DESC, last_seen_at DESC
        LIMIT 50
      `);

      const data = (Array.isArray(rows) ? rows : (rows as any).rows ?? []) as Array<{
        spoken_item: string;
        resolution_status: string;
        occurrences: number;
        avg_score: number;
        last_seen_at: string;
        matched_item_id: string | null;
      }>;

      return res.json({ days, rows: data });
    } catch (err: any) {
      console.error("[reports/voice-interpret-failures] error:", err);
      return res.status(500).json({ error: "Failed to fetch voice interpret failures" });
    }
  });

  // ============ TRANSFER ORDERS ============
  app.get("/api/transfer-orders", requireAuth, requireTier("platform"), async (req, res) => {
    // @ts-ignore
    const orders = await storage.getTransferOrders(req.companyId!);
    // @ts-ignore
    const stores = await storage.getCompanyStores(req.companyId!);
    // @ts-ignore
    const inventoryItems = await storage.getInventoryItems(undefined, undefined, req.companyId!);
    
    // Collect user IDs for batch lookup
    const userIds: string[] = [];
    for (const order of orders) {
      if (order.createdBy) userIds.push(order.createdBy);
      if (order.executedBy) userIds.push(order.executedBy);
      if (order.receivedBy) userIds.push(order.receivedBy);
    }
    // @ts-ignore
    const userMap = await storage.getUsersByIds(userIds, req.companyId!);
    
    // Get all transfer order lines to calculate values
    const ordersWithDetails = await Promise.all(orders.map(async order => {
      const fromStore = stores.find(s => s.id === order.fromStoreId);
      const toStore = stores.find(s => s.id === order.toStoreId);
      
      // Get lines for this order and calculate total value
      const lines = await storage.getTransferOrderLines(order.id);
      const totalValue = lines.reduce((sum, line) => {
        const item = inventoryItems.find(i => i.id === line.inventoryItemId);
        const price = item?.pricePerUnit || 0;
        return sum + (line.requestedQty * price);
      }, 0);
      
      return {
        ...order,
        fromStoreName: fromStore?.name || "Unknown",
        toStoreName: toStore?.name || "Unknown",
        totalValue,
        createdByName: order.createdBy ? userMap.get(order.createdBy)?.fullName || null : null,
        executedByName: order.executedBy ? userMap.get(order.executedBy)?.fullName || null : null,
        receivedByName: order.receivedBy ? userMap.get(order.receivedBy)?.fullName || null : null,
      };
    }));
    
    // Sort by expected date descending (most recent first), null dates at the end
    ordersWithDetails.sort((a, b) => {
      if (!a.expectedDate && !b.expectedDate) return 0;
      if (!a.expectedDate) return 1;
      if (!b.expectedDate) return -1;
      return new Date(b.expectedDate).getTime() - new Date(a.expectedDate).getTime();
    });
    
    res.json(ordersWithDetails);
  });

  // @ts-ignore
  app.get("/api/transfer-orders/:id", requireAuth, requireTier("platform"), async (req, res) => {
    // @ts-ignore
    const order = await storage.getTransferOrder(req.params.id);
    if (!order) {
      return res.status(404).json({ error: "Transfer order not found" });
    }
    
    // Verify tenant access: use req.companyId which is set by requireAuth middleware
    // This handles both regular users and global admins consistently
    // @ts-ignore
    if (!req.companyId || order.companyId !== req.companyId) {
      return res.status(403).json({ error: "Access denied" });
    }
    
    const lines = await storage.getTransferOrderLines(order.id);
    const stores = await storage.getCompanyStores(order.companyId);
    const inventoryItems = await storage.getInventoryItems();
    const units = await storage.getUnits();
    
    // Collect user IDs for batch lookup - use order's companyId for tenant isolation
    const userIds: string[] = [];
    if (order.createdBy) userIds.push(order.createdBy);
    if (order.executedBy) userIds.push(order.executedBy);
    if (order.receivedBy) userIds.push(order.receivedBy);
    const userMap = await storage.getUsersByIds(userIds, order.companyId);
    
    const linesWithDetails = lines.map(line => {
      const item = inventoryItems.find(i => i.id === line.inventoryItemId);
      const unit = units.find(u => u.id === line.unitId);
      return {
        ...line,
        itemName: item?.name || "Unknown",
        unitName: unit?.name || "Unknown",
      };
    });
    
    const fromStore = stores.find(s => s.id === order.fromStoreId);
    const toStore = stores.find(s => s.id === order.toStoreId);
    
    res.json({
      ...order,
      fromStoreName: fromStore?.name || "Unknown",
      toStoreName: toStore?.name || "Unknown",
      lines: linesWithDetails,
      createdByName: order.createdBy ? userMap.get(order.createdBy)?.fullName || null : null,
      executedByName: order.executedBy ? userMap.get(order.executedBy)?.fullName || null : null,
      receivedByName: order.receivedBy ? userMap.get(order.receivedBy)?.fullName || null : null,
    });
  });

