  // ── Operating Units CRUD ─────────────────────────────────────────────────────
  // Operating units are the revenue-producing areas within an operating location
  // (Dining Room, Bar, Patio, Catering, etc.).  They are stored in
  // inventory_locations with locationType = 'operating_unit'.

  // GET /api/operating-units — list all active operating units for the company
  app.get("/api/operating-units", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId as string | undefined;
      if (!companyId) return res.status(400).json({ error: "Company context required." });

      const units = await db
        .select({
          id: inventoryLocations.id,
          name: inventoryLocations.name,
          locationType: inventoryLocations.locationType,
          sourceSystem: inventoryLocations.sourceSystem,
          active: inventoryLocations.active,
        })
        .from(inventoryLocations)
        .where(
          and(
            // @ts-ignore
            eq(inventoryLocations.companyId, companyId),
            // @ts-ignore
            eq(inventoryLocations.locationType, "operating_unit"),
          ),
        )
        .orderBy(inventoryLocations.name);

      return res.json(units);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return res.status(500).json({ error: msg });
    }
  });

  // POST /api/operating-units — create a new operating unit (manager+)
  app.post("/api/operating-units", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId as string | undefined;
      if (!companyId) return res.status(400).json({ error: "Company context required." });

      // @ts-ignore
      const currentUser = await storage.getUser(req.user!.id);
      const role = currentUser?.role ?? "store_user";
      const ALLOWED_ROLES = ["store_manager", "company_admin", "global_admin"] as const;
      if (!(ALLOWED_ROLES as readonly string[]).includes(role)) {
        return res.status(403).json({ error: "Manager or admin role required to manage operating units." });
      }

      const { name } = req.body as { name?: string };
      if (!name?.trim()) return res.status(400).json({ error: "name is required." });

      const normalizedName = name.trim().toLowerCase();

      // Dedup check
      const [existing] = await db
        .select({ id: inventoryLocations.id })
        .from(inventoryLocations)
        .where(
          and(
            // @ts-ignore
            eq(inventoryLocations.companyId, companyId),
            // @ts-ignore
            eq(inventoryLocations.locationType, "operating_unit"),
            // @ts-ignore
            eq(inventoryLocations.normalizedName, normalizedName),
          ),
        )
        .limit(1);
      if (existing) return res.status(409).json({ error: "An operating unit with that name already exists." });

      const [created] = await db
        .insert(inventoryLocations)
        .values({
          companyId,
          name: name.trim(),
          normalizedName,
          locationType: "operating_unit",
          sourceSystem: "manual",
          active: 1,
        })
        .returning();

      return res.status(201).json(created);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return res.status(500).json({ error: msg });
    }
  });

  // PATCH /api/operating-units/:id — rename or toggle active (manager+)
  app.patch("/api/operating-units/:id", requireAuth, async (req, res) => {
    try {
      const companyId = (req as any).companyId as string | undefined;
      if (!companyId) return res.status(400).json({ error: "Company context required." });

      // @ts-ignore
      const currentUser = await storage.getUser(req.user!.id);
      const role = currentUser?.role ?? "store_user";
      const ALLOWED_ROLES = ["store_manager", "company_admin", "global_admin"] as const;
      if (!(ALLOWED_ROLES as readonly string[]).includes(role)) {
        return res.status(403).json({ error: "Manager or admin role required to manage operating units." });
      }

      const { id } = req.params;
      const { name, active } = req.body as { name?: string; active?: number };

      const [unit] = await db
        .select({ id: inventoryLocations.id })
        .from(inventoryLocations)
        .where(
          and(
            // @ts-ignore
            eq(inventoryLocations.id, id),
            // @ts-ignore
            eq(inventoryLocations.companyId, companyId),
            // @ts-ignore
            eq(inventoryLocations.locationType, "operating_unit"),
          ),
        )
        .limit(1);
      if (!unit) return res.status(404).json({ error: "Operating unit not found." });

      const updates: Record<string, unknown> = { updatedAt: new Date() };
      if (name !== undefined) {
        updates.name = name.trim();
        updates.normalizedName = name.trim().toLowerCase();
      }
      if (active !== undefined) updates.active = active ? 1 : 0;

      const [updated] = await db
        .update(inventoryLocations)
        .set(updates as any)
        // @ts-ignore
        .where(eq(inventoryLocations.id, id))
        .returning();

      return res.json(updated);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      return res.status(500).json({ error: msg });
    }
  });

  // Backward-compat alias: old path used by pre-966 clients
  app.get("/api/inventory-locations/outlets", requireAuth, async (req, res) => {
    const companyId = (req as any).companyId as string | undefined;
    if (!companyId) return res.status(400).json({ error: "Company context required." });
    const units = await db
      .select({ id: inventoryLocations.id, name: inventoryLocations.name,
                 locationType: inventoryLocations.locationType,
                 sourceSystem: inventoryLocations.sourceSystem, active: inventoryLocations.active })
      .from(inventoryLocations)
      // @ts-ignore
      .where(and(eq(inventoryLocations.companyId, companyId), eq(inventoryLocations.locationType, "operating_unit"), eq(inventoryLocations.active, 1)))
      .orderBy(inventoryLocations.name);
    return res.json(units);
  });

  // Get accessible stores for current user (filtered by role and assignments)
  // @ts-ignore
  app.get("/api/stores/accessible", requireAuth, async (req, res) => {
    try {
      // @ts-ignore
      const currentUser = await storage.getUser(req.user!.id);
      if (!currentUser) {
        return res.status(401).json({ error: "User not found" });
      }

      // Get effective company ID from request context (already resolved by auth middleware)
      const effectiveCompanyId = (req as any).companyId;

      // Get accessible store IDs
      const storeIds = await getAccessibleStores(currentUser, effectiveCompanyId || undefined);
      
      // Fetch full store objects
      const stores = [];
      for (const storeId of storeIds) {
        const store = await storage.getCompanyStore(storeId);
        if (store) {
          stores.push(store);
        }
      }
      
      res.json(stores);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // @ts-ignore
  app.post("/api/companies", requireAuth, async (req, res) => {
    // @ts-ignore
    const user = await storage.getUser(req.user!.id);
    
    // Only global admins can create companies
    if (user?.role !== "global_admin") {
      return res.status(403).json({ error: "Only global admins can create companies" });
    }

    try {
      const data = insertCompanySchema.parse(req.body);

      // Normalize 'none' → null before writing to the DB ('none' is a UI-only
      // sentinel; the DB CHECK constraint only permits real provider values or NULL).
      if (data.posProvider === "none") {
        data.posProvider = undefined;
      }

      // @ts-ignore
      const { company, defaultStore } = await db.transaction(async (tx) => {
        // Create the company
        const [newCompany] = await tx
          .insert(companiesTable)
          .values(data)
          .returning();

        // Auto-create a default store so admins don't land on "No Stores"
        const storeCode = newCompany.name
          .toUpperCase()
          .replace(/[^A-Z0-9]/g, "")
          .slice(0, 6) || "STORE1";
        const [newStore] = await tx
          .insert(companyStores)
          .values({
            companyId: newCompany.id,
            code: storeCode,
            name: `${newCompany.name}'s Store`,
          })
          .returning();

        // Create default storage locations
        const defaultLocations = [
          { name: "Walk-In Cooler", sortOrder: 1 },
          { name: "Pantry", sortOrder: 2 },
          { name: "Drink Cooler", sortOrder: 3 },
          { name: "Walk-In Freezer", sortOrder: 4 },
          { name: "Prep Table", sortOrder: 5 },
          { name: "Front Counter", sortOrder: 6 },
        ];
        for (const location of defaultLocations) {
          await tx.insert(storageLocations).values({
            companyId: newCompany.id,
            ...location,
          });
        }

        return { company: newCompany, defaultStore: newStore };
      });

      res.status(201).json({ ...company, defaultStore });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // @ts-ignore
  app.patch("/api/companies/:id", requireAuth, async (req, res) => {
    // @ts-ignore
    const user = await storage.getUser(req.user!.id);
    
    // Only global admins can update companies
    if (user?.role !== "global_admin") {
      return res.status(403).json({ error: "Only global admins can update companies" });
    }

    try {
      const data = insertCompanySchema.partial().parse(req.body);

      // ── POS provider/method validation ──────────────────────────────────────
      const isPosChange = "posProvider" in data || "primarySalesMethod" in data;
      if (isPosChange) {
        // @ts-ignore
        const currentCompany = await storage.getCompany(req.params.id);
        if (!currentCompany) {
          return res.status(404).json({ error: "Company not found" });
        }
        const resultingProvider = "posProvider" in data ? data.posProvider : currentCompany.posProvider;
        const resultingMethod = "primarySalesMethod" in data
          ? (data as any).primarySalesMethod
          : (currentCompany as any).primarySalesMethod;

        // Rule 1: null/none provider requires null method.
        if (!resultingProvider || resultingProvider === "none") {
          if (resultingMethod) {
            return res.status(422).json({
              code: "invalid_pos_configuration",
              error: "primarySalesMethod must be null when no POS provider is selected.",
            });
          }
        }

        // Rule 2: pos_connector requires a registry-available adapter with salesRetrieval.
        if (resultingMethod === "pos_connector") {
          if (!resultingProvider || !providerSupportsElectronic(resultingProvider)) {
            return res.status(422).json({
              code: "invalid_pos_configuration",
              error: `The selected POS provider (${resultingProvider ?? "none"}) does not support an electronic connection. ` +
                "Choose a provider with an available connector, or set primarySalesMethod to manual_upload.",
            });
          }
        }

        // Rule 3: manual_upload allowed for any recognised provider (including "other").
        if (resultingMethod === "manual_upload") {
          if (resultingProvider && resultingProvider !== "none" && !isKnownProvider(resultingProvider)) {
            return res.status(422).json({
              code: "invalid_pos_configuration",
              error: `Unknown POS provider: ${resultingProvider}.`,
            });
          }
        }

        // Rule 4: provider-change guard — block if any retained connection exists.
        if ("posProvider" in data && data.posProvider !== currentCompany.posProvider) {
          // @ts-ignore
          const retained = await storage.getRetainedPosConnectionForCompany(req.params.id);
          if (retained) {
            return res.status(409).json({
              code: "retained_pos_connection",
              error: "Cannot change POS provider while a connection exists. Disconnect the current connection first.",
              provider: retained.provider,
              connectionId: retained.id,
              connectionStatus: retained.status,
            });
          }
        }
      }
      // ── End POS validation ──────────────────────────────────────────────────

      // Normalize 'none' → null before writing to the DB (the DB CHECK constraint
      // only permits real provider values or NULL; 'none' is a UI-only sentinel).
      if ("posProvider" in data && (data.posProvider === "none" || !data.posProvider)) {
        (data as any).posProvider = null;
      }

      // @ts-ignore
      const company = await storage.updateCompany(req.params.id, data);
      
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }
      
      res.json(company);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // PATCH /api/companies/:id/pos-config — update posProvider + primarySalesMethod atomically.
  // Allowed for owner/company_admin (own company) or global_admin.
  // The generic PATCH /api/companies/:id is global_admin-only; this scoped endpoint lets
  // company admins and owners configure their POS integration without broader admin access.
  // @ts-ignore
  app.patch("/api/companies/:id/pos-config", requireAuth, async (req, res) => {
    const user = (req as any).user;
    const isAdminRole =
      user?.role === "global_admin" ||
      user?.role === "company_admin" ||
      user?.role === "owner";
    if (!isAdminRole) {
      return res.status(403).json({ error: "Admin access required" });
    }
    if (user?.role !== "global_admin" && user?.companyId !== req.params.id) {
      return res.status(403).json({ error: "Can only update your own company" });
    }

    try {
      const body = z.object({
        posProvider: z
          .enum(POS_PROVIDER_VALUES)
          .nullable()
          .optional(),
        primarySalesMethod: z
          .enum(["pos_connector", "manual_upload"])
          .nullable()
          .optional(),
      }).parse(req.body);

      // @ts-ignore
      const currentCompany = await storage.getCompany(req.params.id);
      if (!currentCompany) {
        return res.status(404).json({ error: "Company not found" });
      }

      const resultingProvider =
        "posProvider" in body ? body.posProvider : currentCompany.posProvider;
      const resultingMethod =
        "primarySalesMethod" in body
          ? body.primarySalesMethod
          : (currentCompany as any).primarySalesMethod ?? null;

      // Rule 1: null/none provider requires null method.
      if (!resultingProvider || resultingProvider === "none") {
        if (resultingMethod) {
          return res.status(422).json({
            code: "invalid_pos_configuration",
            error: "primarySalesMethod must be null when no POS provider is selected.",
          });
        }
      }

      // Rule 2: pos_connector requires a registry-available adapter with salesRetrieval.
      if (resultingMethod === "pos_connector") {
        if (!resultingProvider || !providerSupportsElectronic(resultingProvider)) {
          return res.status(422).json({
            code: "invalid_pos_configuration",
            error:
              `The selected POS provider (${resultingProvider ?? "none"}) does not support an electronic connection. ` +
              "Choose a provider with an available connector, or set primarySalesMethod to manual_upload.",
          });
        }
      }

      // Rule 3: manual_upload allowed for any recognised provider.
      if (resultingMethod === "manual_upload") {
        if (
          resultingProvider &&
          resultingProvider !== "none" &&
          !isKnownProvider(resultingProvider)
        ) {
          return res.status(422).json({
            code: "invalid_pos_configuration",
            error: `Unknown POS provider: ${resultingProvider}.`,
          });
        }
      }

      // Rule 4: provider-change guard — block if any retained connection exists.
      if ("posProvider" in body && body.posProvider !== currentCompany.posProvider) {
        // @ts-ignore
        const retained = await storage.getRetainedPosConnectionForCompany(req.params.id);
        if (retained) {
          return res.status(409).json({
            code: "retained_pos_connection",
            error:
              "Cannot change POS provider while a connection exists. Disconnect the current connection first.",
            provider: retained.provider,
            connectionId: retained.id,
            connectionStatus: retained.status,
          });
        }
      }

      const updatePayload: Record<string, any> = {};
      if ("posProvider" in body) {
        updatePayload.posProvider =
          !body.posProvider || body.posProvider === "none" ? null : body.posProvider;
      }
      if ("primarySalesMethod" in body) {
        updatePayload.primarySalesMethod = body.primarySalesMethod ?? null;
      }

      // @ts-ignore
      const updated = await storage.updateCompany(req.params.id, updatePayload);
      if (!updated) {
        return res.status(404).json({ error: "Company not found" });
      }

      res.json(updated);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // PATCH /api/companies/:id/costing-method — set company costing method (Last Cost vs WAC)
  // Allowed for owner/company_admin (own company) or global_admin. Triggers full recipe recalculation.
  // @ts-ignore
  app.patch("/api/companies/:id/costing-method", requireAuth, async (req, res) => {
    const user = (req as any).user;
    const isAdminRole = user?.role === "global_admin" || user?.role === "company_admin" || user?.role === "owner";
    if (!isAdminRole) {
      return res.status(403).json({ error: "Admin access required" });
    }
    if (user?.role !== "global_admin" && user?.companyId !== req.params.id) {
      return res.status(403).json({ error: "Can only update your own company" });
    }

    try {
      const { costingMethod } = z.object({
        costingMethod: z.enum(["last_cost", "weighted_average"]),
      }).parse(req.body);

      // @ts-ignore
      const existingCompany = await storage.getCompany(req.params.id);
      if (!existingCompany) {
        return res.status(404).json({ error: "Company not found" });
      }

      // Pre-compute every recipe's new cost using the *target* method BEFORE
      // persisting the company flip. If any recipe cost computation throws,
      // we abort and the company method stays on its old value — no partial
      // state. Only after every recipe cost is computed do we commit
      // (company update + recipe updates) atomically inside one transaction.
      const targetCompany = { ...existingCompany, costingMethod };

      // @ts-ignore
      const allRecipes = await storage.getRecipes(req.params.id);
      const componentsByRecipe = new Map<string, RecipeComponent[]>();
      for (const r of allRecipes) {
        componentsByRecipe.set(r.id, await storage.getRecipeComponents(r.id));
      }

      // Build child-first topological order across ALL recipes for this company
      // using an explicit (iterative) DFS so a deep recipe graph cannot blow
      // the JS call stack, and detect cycles up-front (a recipe transitively
      // depending on itself via canBeIngredient) so the recalc fails cleanly
      // with the offending recipe ids rather than mis-ordering the recompute.
      type Frame = { id: string; childIdx: number };
      const visited = new Set<string>();
      const onStack = new Set<string>();
      const sorted: string[] = [];
      let cycleIds: string[] | null = null;

      const childRecipeIdsOf = (recipeId: string): string[] => {
        const comps = componentsByRecipe.get(recipeId) || [];
        const out: string[] = [];
        for (const c of comps) {
          if (c.componentType === "recipe" && componentsByRecipe.has(c.componentId)) {
            out.push(c.componentId);
          }
        }
        return out;
      };

      for (const root of allRecipes) {
        if (visited.has(root.id)) continue;
        const stack: Frame[] = [{ id: root.id, childIdx: 0 }];
        onStack.add(root.id);
        while (stack.length > 0) {
          const top = stack[stack.length - 1];
          const children = childRecipeIdsOf(top.id);
          if (top.childIdx < children.length) {
            const childId = children[top.childIdx++];
            if (onStack.has(childId)) {
              // Cycle: collect the offending recipe ids from the current path
              const startIdx = stack.findIndex((f) => f.id === childId);
              cycleIds = stack.slice(startIdx).map((f) => f.id).concat(childId);
              break;
            }
            if (!visited.has(childId)) {
              stack.push({ id: childId, childIdx: 0 });
              onStack.add(childId);
            }
          } else {
            visited.add(top.id);
            onStack.delete(top.id);
            sorted.push(top.id);
            stack.pop();
          }
        }
        if (cycleIds) break;
      }

      if (cycleIds) {
        const uniqueCycle = Array.from(new Set(cycleIds));
        return res.status(409).json({
          error: `Recipe cycle detected — costing recalculation aborted. Recipes in cycle: ${uniqueCycle.join(", ")}`,
          cycleRecipeIds: uniqueCycle,
        });
      }

      const memo = new Map<string, number>();
      const newCosts = new Map<string, number>();
      for (const recipeId of sorted) {
        const newCost = await calculateRecipeCost(recipeId, { company: targetCompany }, memo);
        newCosts.set(recipeId, newCost);
      }

      // All recipe costs computed successfully — now commit company flip and
      // recipe updates atomically. If any recipe write fails, the entire
      // transaction rolls back and the company costing method stays on its
      // old value.
      // @ts-ignore
      const company = await db.transaction(async (tx) => {
        const [updatedCompany] = await tx
          .update(companiesTable)
          .set({ costingMethod })
          // @ts-ignore
          .where(eq(companiesTable.id, req.params.id))
          .returning();
        if (!updatedCompany) {
          throw new Error("Company not found");
        }
        for (const [recipeId, newCost] of newCosts) {
          await tx
            .update(recipes)
            .set({ computedCost: newCost })
            // @ts-ignore
            .where(eq(recipes.id, recipeId));
        }
        return updatedCompany;
      });

      // @ts-ignore
      await cacheInvalidator.invalidateRecipes(req.params.id);
      // Inventory list/detail responses include a derived effectiveUnitCost
      // computed from the company's costing method, so the cached enriched
      // payload must be invalidated when that method flips.
      // @ts-ignore
      await cacheInvalidator.invalidateInventory(req.params.id);

      res.json({ ...company, recipesRecalculated: newCosts.size });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  /**
   * DELETE /api/admin/companies/:id/purge
   * 
   * Admin-only endpoint to purge all data for a company.
   * Deletes only the target company's data (multi-tenant safe).
   * 
   * Query params:
   *   ?dryRun=true - Show what would be deleted without actually deleting
   * 
   * Security:
   *   - Requires global_admin role
   */
  // @ts-ignore
  app.delete("/api/admin/companies/:id/purge", requireAuth, async (req, res) => {
    // @ts-ignore
    const user = await storage.getUser(req.user!.id);
    
    // Only global admins can purge companies
    if (user?.role !== "global_admin") {
      return res.status(403).json({ error: "Only global admins can purge companies" });
    }

    const companyId = req.params.id;
    const dryRun = req.query.dryRun === 'true';

    try {
      // Verify company exists
      // @ts-ignore
      const company = await storage.getCompany(companyId);
      if (!company) {
        return res.status(404).json({ error: "Company not found" });
      }

      // Execute purge (or dry-run)
      // @ts-ignore
      const stats = await purgeCompanyData(companyId, dryRun);

      // Calculate summary
      const totalRows = stats.reduce((sum, s) => sum + s.rowsDeleted, 0);
      const tablesAffected = stats.filter(s => s.rowsDeleted > 0);

      res.json({
        success: true,
        dryRun,
        company: {
          id: company.id,
          name: company.name,
        },
        summary: {
          totalRowsDeleted: totalRows,
          tablesAffected: tablesAffected.length,
        },
        details: stats.filter(s => s.rowsDeleted > 0),
      });
    } catch (error: any) {
      console.error("Error purging company:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // @ts-ignore
  app.patch("/api/admin/companies/:id/subscription", requireAuth, async (req, res) => {
    try {
      // @ts-ignore
      const user = await storage.getUser(req.user!.id);
      if (user?.role !== "global_admin") {
        return res.status(403).json({ error: "Only global admins can update subscriptions" });
      }

      const { tier, status } = req.body;
      const validTiers = ["platform", "enterprise"];
      const validStatuses = ["active", "past_due", "canceled", "trialing", "incomplete"];

      if (tier && !validTiers.includes(tier)) {
        return res.status(400).json({ error: `Invalid tier. Must be one of: ${validTiers.join(", ")}` });
      }
      if (status && !validStatuses.includes(status)) {
        return res.status(400).json({ error: `Invalid status. Must be one of: ${validStatuses.join(", ")}` });
      }

      const updates: Record<string, any> = {};
      if (tier) updates.subscriptionPlan = tier;
      if (status) updates.subscriptionStatus = status;

      if (Object.keys(updates).length === 0) {
        return res.status(400).json({ error: "At least one of tier or status is required" });
      }

      // @ts-ignore
      const updated = await storage.updateCompany(req.params.id, updates);
      if (!updated) {
        return res.status(404).json({ error: "Company not found" });
      }

      res.json(updated);
    } catch (error: any) {
      console.error("Error updating subscription:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Chat-log and chat-correction routes — see server/routes/chatLogsRoutes.ts
  registerChatLogsRoutes(app);

  // GET /api/admin/users — global admin: full cross-company user roster with last-login stats
  // @ts-ignore
  app.get("/api/admin/users", requireAuth, async (req, res) => {
    type UserRow = {
      id: string;
      email: string;
      first_name: string | null;
      last_name: string | null;
      role: string;
      active: number;
      created_at: string;
      company_id: string | null;
      company_name: string | null;
      subscription_plan: string | null;
      last_login_at: string | null;
      active_session_count: string;
    };

    try {
      // @ts-ignore
      const reqUser = await storage.getUser(req.user!.id);
      if (reqUser?.role !== "global_admin") {
        return res.status(403).json({ error: "Only global admins can access this endpoint" });
      }
      const search = typeof req.query.search === "string"
        ? req.query.search.toLowerCase()
        : undefined;

      const result = await db.execute(
        sql`SELECT u.id, u.email, u.first_name, u.last_name, u.role, u.active, u.created_at,
                   c.id as company_id, c.name as company_name, c.subscription_plan,
                   MAX(s.last_active_at) as last_login_at,
                   COUNT(CASE WHEN s.revoked_at IS NULL AND s.expires_at > NOW() THEN 1 END) as active_session_count,
                   COUNT(CASE WHEN s.revoked_at IS NULL AND s.expires_at > NOW() AND s.source = 'mobile' THEN 1 END) as mobile_session_count
            FROM users u
            LEFT JOIN companies c ON u.company_id = c.id
            LEFT JOIN auth_sessions s ON s.user_id = u.id
            WHERE (u.company_id IS NULL OR c.id IS NOT NULL)
            GROUP BY u.id, u.email, u.first_name, u.last_name, u.role, u.active, u.created_at,
                     c.id, c.name, c.subscription_plan
            ORDER BY u.created_at DESC`
      );

      // Neon driver wraps rows in a .rows property; fall back for other drivers
      const rawRows = (result as { rows?: UserRow[] }).rows ?? (result as UserRow[]);
      let allRows: UserRow[] = Array.isArray(rawRows) ? rawRows : [];

      if (search) {
        allRows = allRows.filter((r) => {
          const name = `${r.first_name ?? ""} ${r.last_name ?? ""}`.toLowerCase();
          return (
            name.includes(search) ||
            (r.email ?? "").toLowerCase().includes(search) ||
            (r.company_name ?? "").toLowerCase().includes(search)
          );
        });
      }

      const todayStart = new Date();
      todayStart.setUTCHours(0, 0, 0, 0);

      const totalUsers = allRows.length;
      const activeUsers = allRows.filter((r) => r.active === 1).length;
      const inactiveUsers = totalUsers - activeUsers;
      const activeToday = allRows.filter(
        (r) => r.last_login_at !== null && new Date(r.last_login_at) >= todayStart
      ).length;

      res.json({
        users: allRows,
        stats: { totalUsers, activeUsers, inactiveUsers, activeToday },
      });
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Unknown error";
      console.error("GET /api/admin/users error:", err);
      res.status(500).json({ error: message });
    }
  });

