  // POST /api/purchase-orders/:id/reconcile - Save reconciliation data (invoice # + totals + initials)
  // @ts-ignore
  app.post("/api/purchase-orders/:id/reconcile", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      // @ts-ignore
      const { companyId, id: userId } = req.user!;
      const { id: purchaseOrderId } = req.params;

      // Verify QB connected
      const connection = await storage.getQuickBooksConnection(companyId);
      if (!connection) return res.status(400).json({ error: "QuickBooks is not connected. Please connect in Settings." });

      // @ts-ignore
      const po = await storage.getPurchaseOrder(purchaseOrderId, companyId);
      if (!po) return res.status(404).json({ error: "Purchase order not found" });
      if (po.status !== "received" && po.status !== "pending_qb_export") {
        return res.status(400).json({ error: "Purchase order must be in received status to reconcile" });
      }

      const { invoiceNumber, invoiceDate, invoiceTotal, taxAmount, initials, notes, receiptId } = req.body;
      if (invoiceTotal == null || !receiptId) {
        return res.status(400).json({ error: "invoiceTotal and receiptId are required" });
      }
      const trimmedInitials = (initials || "").trim();
      if (!trimmedInitials || trimmedInitials.length < 2 || trimmedInitials.length > 4) {
        return res.status(400).json({ error: "initials is required and must be 2–4 characters" });
      }

      // Validate receipt belongs to this PO and company
      const receipts = await storage.getReceipts(companyId);
      const receipt = receipts.find(r => r.id === receiptId && r.purchaseOrderId === purchaseOrderId);
      if (!receipt) {
        return res.status(400).json({ error: "Receipt not found or does not belong to this purchase order" });
      }

      // Compute system total from server-side receipt lines — never trust client-supplied total
      const lines = await storage.getReceiptLinesByReceiptId(receiptId);
      const systemTotal = parseFloat(
        lines.reduce((sum, l) => sum + (parseFloat(String(l.receivedQty || 0)) * parseFloat(String(l.priceEach || 0))), 0).toFixed(2)
      );

      const taxNum = parseFloat(taxAmount || 0);
      const invoiceNum = parseFloat(invoiceTotal);
      const receiptNum = systemTotal;
      const variance = parseFloat((invoiceNum + taxNum - receiptNum).toFixed(2));

      // @ts-ignore
      const existing = await storage.getQbReconciliation(purchaseOrderId, companyId);
      let rec;
      if (existing) {
        // @ts-ignore
        rec = await storage.updateQbReconciliation(purchaseOrderId, companyId, {
          invoiceNumber: invoiceNumber || null,
          invoiceDate: invoiceDate ? new Date(invoiceDate) : null,
          invoiceTotal: invoiceNum,
          taxAmount: taxNum,
          receiptTotal: receiptNum,
          variance,
          initials: trimmedInitials,
          notes: notes || null,
          reconciledBy: userId,
          reconciledAt: new Date(),
        });
      } else {
        rec = await storage.createQbReconciliation({
          companyId,
          // @ts-ignore
          purchaseOrderId,
          receiptId,
          invoiceNumber: invoiceNumber || null,
          invoiceDate: invoiceDate ? new Date(invoiceDate) : null,
          invoiceTotal: invoiceNum,
          taxAmount: taxNum,
          receiptTotal: receiptNum,
          variance,
          initials: trimmedInitials,
          notes: notes || null,
          reconciledBy: userId,
        });
      }

      // Advance PO status to pending_qb_export only when coming from received
      if (po.status === "received") {
        // @ts-ignore
        await storage.updatePurchaseOrder(purchaseOrderId, { status: "pending_qb_export" });
      }

      res.json({ data: rec });
    } catch (error: any) {
      console.error("Reconcile error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // POST /api/quickbooks/export-bills - Export one or more reconciled POs as QB Bills
  // @ts-ignore
  app.post("/api/quickbooks/export-bills", requireAuth, requireTier("platform"), async (req, res) => {
    try {
      // @ts-ignore
      const { companyId } = req.user!;
      const { purchaseOrderIds } = req.body as { purchaseOrderIds: string[] };

      if (!Array.isArray(purchaseOrderIds) || purchaseOrderIds.length === 0) {
        return res.status(400).json({ error: "purchaseOrderIds array is required" });
      }

      // Check QB connection
      const connection = await storage.getQuickBooksConnection(companyId);
      if (!connection) {
        return res.status(400).json({ error: "QuickBooks is not connected. Please connect in Settings." });
      }

      const { createBillFromReceipt } = await import("./services/quickbooks");

      const results: Array<{ poId: string; success: boolean; quickbooksBillId?: string; error?: string }> = [];

      for (const poId of purchaseOrderIds) {
        const po = await storage.getPurchaseOrder(poId, companyId);
        if (!po) {
          results.push({ poId, success: false, error: "Purchase order not found" });
          continue;
        }
        // Only allow orders that have been reconciled (pending_qb_export status)
        if (po.status !== "pending_qb_export") {
          results.push({ poId, success: false, error: "Order must be reconciled before exporting to QuickBooks" });
          continue;
        }

        const result = await createBillFromReceipt(companyId, poId);
        results.push({ poId, success: result.success, quickbooksBillId: result.quickbooksBillId, error: result.error });

        if (result.success) {
          await storage.updatePurchaseOrder(poId, { status: "qb_exported" });
        }
      }

      const successCount = results.filter((r) => r.success).length;
      const failureCount = results.filter((r) => !r.success).length;

      res.json({ data: { results, successCount, failureCount } });
    } catch (error: any) {
      console.error("Export bills error:", error);
      res.status(500).json({ error: error.message });
    }
  });

